module.exports={"K61b15cc0|1":[{"y":2011,"o":18,"s":"I. 证明：对任意的正整数 n，都有 1/(n+1) < ln(1+1/n) < 1/n 成立；II. 设 aₙ = 1+1/2+⋯+1/n-ln n (n = 1,2,⋯)，证明数列 {aₙ} 收敛。","a":"数列 {aₙ} 单调递减且有下界 0，故收敛（极限即欧拉常数 γ ≈ 0.5772）"},{"y":2018,"o":19,"s":"设数列 {xₙ} 满足：x₁ > 0，xₙ e^(xₙ₊₁) = e^(xₙ)-1 (n = 1,2,⋯)。证明数列 {xₙ} 收敛，并求 lim_(n → ∞)xₙ。","a":"lim_(n → ∞)xₙ = 0"},{"y":2019,"o":18,"s":"设 aₙ = ∫₀¹xⁿ√(1-x²) dx (n = 0,1,2,⋯)。I. 证明数列 {aₙ} 单调递减，且 aₙ = (n-1)/(n+2)aₙ₋₂ (n = 2,3,⋯)；II. 求 lim_(n → ∞)aₙ/(aₙ₋₁)。","a":"lim_(n → ∞)aₙ/(aₙ₋₁) = 1"},{"y":2022,"o":3,"s":"已知数列 {xₙ} 满足 -π/2 ≤ xₙ ≤ π/2，则（ ）A. 若 lim_(n → ∞)cos(sin xₙ) 存在，则 lim_(n → ∞)xₙ 存在B. 若 lim_(n → ∞)sin(cos xₙ) 存在，则 lim_(n → ∞)xₙ 存在C. 若 lim_(n → ∞)cos(sin xₙ) 存在，则 lim_(n → ∞)sin xₙ 存在，但 lim_(n → ∞)xₙ 不一定存在D. 若 lim_(n → ∞)sin(cos xₙ) 存在，则 lim_(n → ∞)cos xₙ 存在，但 lim_(n → ∞)xₙ 不一定存在","a":"D"}],"Kc5c67202|1":[{"y":2010,"o":1,"s":"lim_(x → ∞)[x²/((x-a)(x+b))]ˣ = ()A. 1 B. e C. eᵃ⁻ᵇ D. eᵇ⁻ᵃ","a":"C"},{"y":2011,"o":15,"s":"lim_(x → 0)[(ln(1+x))/x]^(1/(eˣ-1))","a":"e^(-1/2)"},{"y":2014,"o":15,"s":"lim_(x → +∞)(∫₁ˣ[t²(e^(1/t)-1)-t]dt)/(x²ln(1+1/x))","a":"1/2"},{"y":2015,"o":9,"s":"lim_(x → 0)(ln(cos x))/x² = underline","a":"-1/2"},{"y":2016,"o":9,"s":"lim_(x → 0)(∫₀ˣtln(1+tsin t) dt)/(1-cos x²) = underline","a":"1/2"},{"y":2020,"o":9,"s":"lim_(x → 0)[1/(eˣ-1)-1/(ln(1+x))] = underline","a":"-1"},{"y":2021,"o":17,"s":"lim_(x → 0)((1+∫₀ˣe^(t²)dt)/(eˣ-1)-1/(sin x))","a":"1/2"},{"y":2025,"o":11,"s":"lim_(x → 0⁺)(xˣ-1)/(ln x·ln(1-x)) = underline","a":"-1"},{"y":2026,"o":12,"s":"lim_(x → 0)(1/x-(ln(1+x))/(xsin x)) = underline","a":"1/2"}],"Ke9053521|1":[{"y":2009,"o":1,"s":"当 x → 0 时，f(x) = x-sin ax 与 g(x) = x²ln(1-bx) 是等价无穷小，则（ ）A. a = 1, b = -1/6 B. a = 1, b = 1/6 C. a = -1, b = -1/6 D. a = -1, b = 1/6","a":"A"},{"y":2013,"o":1,"s":"已知 lim_(x → 0)(x-arctan x)/xᵏ = c，其中 k,c 为常数，且 c ≠0，则（ ）A. k = 2, c = -1/2 B. k = 2, c = 1/2 C. k = 3, c = -1/3 D. k = 3, c = 1/3","a":"D"},{"y":2015,"o":15,"s":"设函数 f(x) = x+aln(1+x)+bxsin x，g(x) = kx³。若 f(x) 与 g(x) 在 x → 0 时是等价无穷小，求 a,b,k 的值。","a":"a = -1，b = -1/2，k = -1/3"},{"y":2018,"o":9,"s":"若 lim_(x → 0)((1-tan x)/(1+tan x))^(1/(ksin x)) = e，则 k = underline","a":"-2"},{"y":2019,"o":1,"s":"当 x → 0 时，若 x-tan x 与 xᵏ 是同阶无穷小，则 k = （ ）A. 1 B. 2 C. 3 D. 4","a":"C"},{"y":2023,"o":11,"s":"当 x → 0 时，函数 f(x) = ax+bx²+ln(1+x) 与 g(x) = e^(x²)-cos x 是等价无穷小，则 ab = underline","a":"-2"},{"y":2024,"o":11,"s":"若 lim_(x → 0)((1+ax²)^(sin x)-1)/x³ = 6，则 a = underline","a":"6"}],"K8946e888|1":[{"y":2020,"o":1,"s":"当 x → 0⁺ 时，下列无穷小量中最高阶的是（ ）A. ∫₀ˣ(e^(t²)-1)dt B. ∫₀ˣln(1+√(t³))dt C. ∫₀^(sin x)sin t² dt D. ∫₀^(1-cos x)√(sin³t) dt","a":"D"}],"Kbcd664b1|1":[{"y":2017,"o":1,"s":"若函数 f(x) = (1-cos√(x))/ax (x > 0)，f(x) = b (x ≤0)，且 f(x) 在 x = 0 处连续，则（ ）A. ab = 1/2 B. ab = -1/2 C. ab = 0 D. ab = 2","a":"A"}],"K547f1fa4|1":[{"y":2015,"o":18,"s":"（本题满分 10 分）I. 设函数 u(x), v(x) 可导，利用导数定义证明 [u(x)v(x)]' = u'(x)v(x)+u(x)v'(x)；II. 设函数 u₁(x),u₂(x),⋯,uₙ(x) 可导，f(x) = u₁(x)u₂(x)⋯ uₙ(x)，写出 f(x) 的求导公式。答案与","a":""},{"y":2016,"o":4,"s":"已知 f(x) = x (x ≤0)，而当 1/(n+1) < x ≤1/n (n = 1,2,⋯) 时 f(x) = 1/n，则（ ）A. x = 0 是 f(x) 的第一类间断点 B. x = 0 是 f(x) 的第二类间断点 C. f(x) 在 x = 0 处连续但不可导 D. f(x) 在 x = 0 处可导","a":"D"},{"y":2018,"o":1,"s":"下列函数中，在 x = 0 处不可导的是（ ）A. f(x) = |x|sin|x| B. f(x) = |x|sin√(|x|) C. f(x) = cos|x| D. f(x) = cos√(|x|)","a":"D"},{"y":2020,"o":2,"s":"设函数 f(x) 在区间 (-1,1) 内有定义，且 lim_(x → 0)f(x) = 0，则（ ）A. 当 lim_(x → 0)(f(x))/(√(|x|)) = 0 时，f(x) 在 x = 0 处可导 B. 当 lim_(x → 0)(f(x))/x² = 0 时，f(x) 在 x = 0 处可导 C. 当 f(x) 在 x = 0 处可导时，lim_(x → 0)(f(x))/(√(|x|)) = 0 D. 当 f(x) 在 x = 0 处可导时，lim_(x → 0)(f(x))/x² = 0","a":"C"},{"y":2021,"o":1,"s":"函数 f(x) = (eˣ-1)/x (x ≠0)，且 f(0) = 1，在 x = 0 处（ ）A. 连续且取得极大值 B. 连续且取得极小值 C. 可导且导数等于零 D. 可导且导数不为零","a":"D"},{"y":2022,"o":1,"s":"设函数 f(x) 满足 lim_(x → 1)(f(x))/(ln x) = 1，则（ ）A. f(1) = 0 B. lim_(x → 1)f(x) = 0 C. f'(1) = 1 D. lim_(x → 1)f'(x) = 1","a":"B"},{"y":2023,"o":3,"s":"设函数 y = f(x) 由 x = 2t+|t|、y = |t|sin t 确定，则（ ）A. f(x) 连续，f'(0) 不存在 B. f'(0) 存在，f'(x) 在 x = 0 处不连续 C. f'(x) 连续，f''(0) 不存在 D. f''(0) 存在，f''(x) 在 x = 0 处不连续","a":"C"},{"y":2024,"o":4,"s":"设函数 f(x) 在区间 (-1,1) 上有定义，且 lim_(x → 0)f(x) = 0，则（ ）A. 当 lim_(x → 0)(f(x))/x = m 时，f'(0) = m B. 当 f'(0) = m 时，lim_(x → 0)(f(x))/x = m C. 当 lim_(x → 0)f'(x) = m 时，f'(0) = m D. 当 f'(0) = m 时，lim_(x → 0)f'(x) = m","a":"B"},{"y":2025,"o":3,"s":"设函数 f(x) 在区间 [0,+∞) 上可导，则（ ）A. 当 lim_(x → +∞)f(x) 存在时，lim_(x → +∞)f'(x) 存在 B. 当 lim_(x → +∞)f'(x) 存在时，lim_(x → +∞)f(x) 存在 C. 当 lim_(x → +∞)(∫₀ˣf(t) dt)/x 存在时，lim_(x → +∞)f(x) 存在 D. 当 lim_(x → +∞)f(x) 存在时，lim_(x → +∞)(∫₀ˣf(t) dt)/x 存在","a":"D"}],"Kde439863|1":[{"y":2010,"o":9,"s":"设 x = e⁻ᵗ，y = ∫₀ᵗln(1+u²)du，则 .d²y/dx²|ₜ₌₀ = ＿＿＿","a":"0"},{"y":2012,"o":2,"s":"设函数 f(x) = (eˣ-1)(e²ˣ-2)⋯(eⁿˣ-n)，其中 n 为正整数，则 f'(0) = （ ）A. (-1)ⁿ⁻¹(n-1)! B. (-1)ⁿ(n-1)! C. (-1)ⁿ⁻¹n! D. (-1)ⁿn!","a":"A"},{"y":2013,"o":9,"s":"设函数 y = f(x) 由方程 y-x = eˣ⁽¹⁻ʸ⁾ 确定，则 lim_(n → ∞)n[f(1/n)-1] = ＿＿＿","a":"1"},{"y":2013,"o":11,"s":"设 x = sin t，y = tsin t+cos t（t 为参数），则 .d²y/dx²|_(t = π/4) = ＿＿＿","a":"√(2)"},{"y":2016,"o":12,"s":"设函数 f(x) = arctan x-x/(1+ax²)，且 f'''(0) = 1，则 a = ＿＿＿","a":"1/2"},{"y":2017,"o":9,"s":"已知函数 f(x) = 1/(1+x²)，则 f⁽³⁾(0) = ＿＿＿","a":"0"},{"y":2020,"o":10,"s":"设 x = √(t²+1)，y = ln(t+√(t²+1))，则 .d²y/dx²|ₜ₌₁ = ＿＿＿","a":"-√(2)"},{"y":2021,"o":12,"s":"设函数 y = y(x) 由参数方程 x = 2eᵗ+t+1、y = 4(t-1)eᵗ+t² 确定，则 .d²y/dx²|ₜ₌₀ = ＿＿＿","a":"2/3"},{"y":2026,"o":13,"s":"设函数 y = y(x) 由参数方程 x = 2sin²t、y = t+cos t，t∈(0,π/2) 确定，则 .d²y/dx²|_(t = π/4) = ＿＿＿","a":"-(√(2))/8"}],"K58d92a92|1":[{"y":2018,"o":10,"s":"设函数 f(x) 具有 2 阶连续导数。若曲线 y = f(x) 过点 (0,0) 且与曲线 y = 2ˣ 在点 (1,2) 处相切，则∫₀¹x f''(x) dx = underline.","a":"2ln 2-2。"}],"Kdd1ee30c|1":[{"y":2010,"o":16,"s":"求函数 f(x) = ∫₁^(x²)(x²-t)e^(-t²)dt 的单调区间与极值。","a":"单调递增区间 (-1,0) 与 (1,+∞)，单调递减区间 (-∞,-1) 与 (0,1)；极小值 f(-1) = f(1) = 0，极大值 f(0) = dfrac12(1-dfrac1e)。"},{"y":2014,"o":16,"s":"设函数 y = f(x) 由方程 y³+xy²+x²y+6 = 0 确定，求 f(x) 的极值。","a":"唯一极小值 f(1) = -2，无极大值。"},{"y":2017,"o":2,"s":"设函数 f(x) 可导，且 f(x)f'(x) > 0，则（ ）(A) f(1) > f(-1) (B) f(1) < f(-1) (C) |f(1)| > |f(-1)| (D) |f(1)| < |f(-1)|","a":"C。"},{"y":2017,"o":17,"s":"已知函数 y(x) 由方程 x³+y³-3x+3y-2 = 0 确定，求 y(x) 的极值。","a":"极大值 y(1) = 1，极小值 y(-1) = 0。"},{"y":2019,"o":2,"s":"设 f(x) = x|x|, x ≤0 xln x, x > 0 ，则 x = 0 是 f(x) 的（ ）(A) 可导点，极值点 (B) 不可导点，极值点 (C) 可导点，非极值点 (D) 不可导点，非极值点","a":"B（且 x = 0 是极大值点）。"},{"y":2026,"o":3,"s":"设函数 f(x) 在区间 [-1,1] 上有定义，则（ ）(A) 当 f(x) 在 (-1,0) 单调递减、在 (0,1) 单调递增时，f(0) 是极小值(B) 当 f(0) 是极小值时，f(x) 在 (-1,0) 单调递减、在 (0,1) 单调递增(C) 当 f(x) 的图形在 [-1,1] 是凹的时，(f(x)-f(1))/(x-1) 在 [-1,1] 单调递增(D) 当 (f(x)-f(1))/(x-1) 在 [-1,1] 单调递增时，f(x) 的图形在 [-1,1] 是凹的","a":"C。"}],"Kac3d5ac3|1":[{"y":2011,"o":1,"s":"曲线 y = (x-1)(x-2)²(x-3)³(x-4)⁴ 的拐点是（ ）(A) (1,0) (B) (2,0) (C) (3,0) (D) (4,0)","a":"C。"},{"y":2012,"o":1,"s":"曲线 y = (x²+x)/(x²-1) 的渐近线的条数为（ ）(A) 0 (B) 1 (C) 2 (D) 3","a":"C，共 2 条：x = 1 与 y = 1。"},{"y":2014,"o":1,"s":"下列曲线中有渐近线的是（ ）(A) y = x+sin x (B) y = x²+sin x (C) y = x+sindfrac1x (D) y = x²+sindfrac1x","a":"C，斜渐近线 y = x。"},{"y":2014,"o":2,"s":"设函数 f(x) 具有 2 阶导数，g(x) = f(0)(1-x)+f(1)x，则在区间 [0,1] 上（ ）(A) 当 f'(x) ≥0 时 f(x) ≥ g(x) (B) 当 f'(x) ≥0 时 f(x) ≤ g(x)(C) 当 f''(x) ≥0 时 f(x) ≥ g(x) (D) 当 f''(x) ≥0 时 f(x) ≤ g(x)","a":"D。"},{"y":2015,"o":1,"s":"设函数 f(x) 在 (-∞,+∞) 上连续，其二阶导函数 f''(x) 的图形如图所示（左侧抛物线与 x 轴相切于 x₁ < 0，右侧曲线在 x = 0 处无定义、在 x₂ > 0 穿过 x 轴），则曲线 y = f(x) 的拐点个数为（ ）(A) 0 (B) 1 (C) 2 (D) 3","a":"C，共 2 个：(0,f(0)) 与 (x₂,f(x₂))。"},{"y":2022,"o":20,"s":"设函数 f(x) 在 (-∞,+∞) 上有二阶连续导数，证明：f''(x) ≥0 的充分必要条件是对任意不同的实数 a,b，都有f((a+b)/2) ≤1/(b-a)∫ₐᵇf(x) dx成立。","a":"证明题，结论即思路 4 中的等价关系。"},{"y":2023,"o":1,"s":"曲线 y = xln(e+1/(x-1)) 的斜渐近线方程为（ ）(A) y = x+e (B) y = x+dfrac1e (C) y = x (D) y = x-dfrac1e","a":"B，y = x+dfrac1e。"},{"y":2025,"o":1,"s":"已知 f(x) = ∫₀ˣe^(t²)sin t dt，g(x) = ∫₀ˣe^(t²)dt·sin²x，则（ ）(A) x = 0 是 f(x) 的极值点，也是 g(x) 的极值点(B) x = 0 是 f(x) 的极值点，(0,0) 是曲线 y = g(x) 的拐点(C) x = 0 是 f(x) 的极值点，(0,0) 是曲线 y = f(x) 的拐点(D) (0,0) 是曲线 y = f(x) 的拐点，也是曲线 y = g(x) 的拐点","a":"B。"}],"K0318406f|1":[{"y":2011,"o":17,"s":"求方程 karctan x-x = 0 不同实根的个数，其中 k 为参数。","a":"当 k ≤1 时只有 1 个实根 x = 0；当 k > 1 时有 3 个不同实根 -a, 0, a（其中 a > √(k-1)）。"},{"y":2017,"o":18,"s":"设函数 f(x) 在区间 [0,1] 上具有 2 阶导数，且 f(1) > 0，lim_(x → 0⁺)(f(x))/x < 0。证明：I. 方程 f(x) = 0 在区间 (0,1) 内至少存在一个实根；II. 方程 f(x)f''(x)+[f'(x)]² = 0 在区间 (0,1) 内至少存在两个不同实根。","a":"证明题，结论即思路 4—6 的罗尔定理链。"}],"K68217a44|1":[{"y":2012,"o":15,"s":"证明：xln(1+x)/(1-x)+cos x ≥1+x²/2(-1 < x < 1)。","a":"证明题，见下述三种证法。"}],"K4586eb88|1":[{"y":2009,"o":18,"s":"I. 证明拉格朗日中值定理：若函数 f(x) 在 [a,b] 上连续，在 (a,b) 内可导，则存在 ξ∈(a,b)，使得 f(b)-f(a) = f'(ξ)(b-a)。II. 证明：若函数 f(x) 在 x = 0 处连续，在 (0,δ) (δ > 0) 内可导，且 lim_(x → 0⁺)f'(x) = A，则 f'₊(0) 存在，且 f'₊(0) = A。","a":"证明题，见思路 1、思路 2。"},{"y":2013,"o":18,"s":"设奇函数 f(x) 在 [-1,1] 上具有二阶导数，且 f(1) = 1。证明：I. 存在 ξ∈(0,1)，使得 f'(ξ) = 1；II. 存在 η∈(-1,1)，使得 f''(η)+f'(η) = 1。","a":"证明题，见思路 1、思路 3。"},{"y":2020,"o":19,"s":"设函数 f(x) 在区间 [0,2] 上具有连续导数，f(0) = f(2) = 0，M = max_(x∈[0,2]){|f(x)|}。证明：I. 存在 ξ∈(0,2)，使得 |f'(ξ)| ≥ M；II. 若对任意的 x∈(0,2)，|f'(x)| ≤ M，则 M = 0。","a":"证明题，结论即思路 4、思路 5。"},{"y":2025,"o":19,"s":"设函数 f(x) 在区间 (a,b) 内可导，证明导函数 f'(x) 在 (a,b) 内严格单调增加的充分必要条件是：对 (a,b) 内任意的 x₁,x₂,x₃，当 x₁ < x₂ < x₃ 时，(f(x₂)-f(x₁))/(x₂-x₁) < (f(x₃)-f(x₂))/(x₃-x₂).","a":"充要条件证明，见思路 6。"},{"y":2026,"o":20,"s":"设可导函数 f(x) 严格单调增加且满足 ∫₋₁¹f(x) dx = 0，记 a = ∫₀¹f(x) dx。(1) 证明 a > 0；(2) 令 F(x) = a(1-x²)+∫₁ˣf(t) dt，证明：存在 ξ∈(-1,1) 使 F''(ξ) = 0。","a":"证明题，(1) 见思路 7，(2) 见思路 8。"}],"K167393e9|1":[{"y":2021,"o":3,"s":"设函数 f(x) = (sin x)/(1+x²) 在 x = 0 处的 3 次泰勒多项式为 ax+bx²+cx³，则（ ）(A) a = 1, b = 0, c = -7/6 (B) a = 1, b = 0, c = 7/6(C) a = -1, b = -1, c = -7/6 (D) a = -1, b = -1, c = 7/6","a":"A。"},{"y":2023,"o":20,"s":"设函数 f(x) 在 [-a,a] 上具有二阶连续导数，证明：I. 若 f(0) = 0，则存在 ξ∈(-a,a)，使得 f''(ξ) = 1/a²l[f(a)+f(-a)r]；II. 若 f(x) 在 (-a,a) 内取得极值，则存在 η∈(-a,a)，使得 |f''(η)| ≥1/2a²l|f(a)-f(-a)r|。","a":"证明题，见思路 2、思路 3。"},{"y":2024,"o":19,"s":"设函数 f(x) 具有 2 阶导数，且 f'(0) = f'(1)，|f''(x)| ≤1。证明：I. 当 x∈(0,1) 时，l|f(x)-f(0)(1-x)-f(1)xr| ≤ (x(1-x))/2；II. |∫₀¹f(x) dx-(f(0)+f(1))/2| ≤1/12。","a":"证明题，见思路 4—6。"}],"K59e1e05f|1":[{"y":2016,"o":2,"s":"已知函数f(x) = 2(x-1), x < 1, ln x, x ≥1 则 f(x) 的一个原函数是（ ）(A) F(x) = (x-1)², x < 1, x(ln x-1), x ≥1 (B) F(x) = (x-1)², x < 1, x(ln x+1)-1, x ≥1 (C) F(x) = (x-1)², x < 1, x(ln x+1)+1, x ≥1 (D) F(x) = (x-1)², x < 1, x(ln x-1)+1, x ≥1","a":"D。"},{"y":2018,"o":15,"s":"求不定积分 ∫ e²ˣarctan√(eˣ-1) dx。","a":"∫ e²ˣarctan√(eˣ-1) dx = e²ˣ/2arctan√(eˣ-1) -1/6(eˣ-1)^(3/2)-frac12√(eˣ-1)+C ."}],"Kd03deadd|1":[{"y":2010,"o":17,"s":"I. 比较 ∫₀¹|ln t| [ln(1+t)]ⁿ dt 与 ∫₀¹ tⁿ|ln t| dt (n = 1,2,⋯) 的大小，说明理由；II. 记 uₙ = ∫₀¹|ln t| [ln(1+t)]ⁿ dt (n = 1,2,⋯)，求极限 lim_(n → ∞)uₙ。","a":"第 I 问 ∫₀¹|ln t| [ln(1+t)]ⁿ dt < ∫₀¹ tⁿ|ln t| dt；第 II 问 lim_(n → ∞)uₙ = 0。"},{"y":2011,"o":4,"s":"设 I = ∫₀^(π/4)ln(sin x) dx，J = ∫₀^(π/4)ln(cot x) dx，K = ∫₀^(π/4)ln(cos x) dx，则 I,J,K 的大小关系为（ ）(A) I < J < K(B) I < K < J(C) J < I < K(D) K < J < I","a":"B。"},{"y":2012,"o":4,"s":"设 Iₖ = ∫₀^(kπ)e^(x²)sin x dx (k = 1,2,3)，则有（ ）(A) I₁ < I₂ < I₃(B) I₃ < I₂ < I₁(C) I₂ < I₃ < I₁(D) I₂ < I₁ < I₃","a":"D。"},{"y":2017,"o":16,"s":"求 lim_(n → ∞)∑ₖ₌₁ⁿk/n²lnl(1+k/nr)。","a":"frac14。"},{"y":2018,"o":4,"s":"设 M = ∫_(-π/2)^(π/2)((1+x)²)/(1+x²) dx，N = ∫_(-π/2)^(π/2)(1+x)/eˣ dx，K = ∫_(-π/2)^(π/2)(1+√(cos x)) dx，则（ ）(A) M > N > K(B) M > K > N(C) K > M > N(D) K > N > M","a":"C。"},{"y":2021,"o":4,"s":"设函数 f(x) 在区间 [0,1] 上连续，则 ∫₀¹ f(x) dx = （ ）(A) lim_(n → ∞)∑ₖ₌₁ⁿfl((2k-1)/2nr)1/2n(B) lim_(n → ∞)∑ₖ₌₁ⁿfl((2k-1)/2nr)1/n(C) lim_(n → ∞)∑ₖ₌₁²ⁿfl((k-1)/2nr)1/n(D) lim_(n → ∞)∑ₖ₌₁²ⁿfl(k/2nr)2/n","a":"B。"},{"y":2022,"o":4,"s":"若 I₁ = ∫₀¹x/(2(1+cos x)) dx，I₂ = ∫₀¹(ln(1+x))/(1+cos x) dx，I₃ = ∫₀¹2x/(1+sin x) dx，则（ ）(A) I₁ < I₂ < I₃(B) I₂ < I₁ < I₃(C) I₁ < I₃ < I₂(D) I₃ < I₂ < I₁","a":"A。"}],"Kc431f98f|1":[{"y":2010,"o":10,"s":"∫₀^(π²)√(x)cos√(x) dx = ＿＿＿","a":"-4π。"},{"y":2012,"o":10,"s":"∫₀² x√(2x-x²) dx = ＿＿＿","a":"π/2。"},{"y":2013,"o":15,"s":"计算 ∫₀¹(f(x))/(√(x)) dx，其中 f(x) = ∫₁ˣ(ln(t+1))/t dt。","a":"8-4ln2-2π。"},{"y":2014,"o":4,"s":"若 ∫_(-π)^π(x-a₁cos x-b₁sin x)²dx = min_(a,b∈R)l{∫_(-π)^π(x-acos x-bsin x)²dxr}，则 a₁cos x+b₁sin x = （ ）(A) 2sin x(B) 2cos x(C) 2πsin x(D) 2πcos x","a":"A。"},{"y":2014,"o":10,"s":"设 f(x) 是周期为 4 的可导奇函数，且 f'(x) = 2(x-1)，x∈[0,2]，则 f(7) = ＿＿＿","a":"1。"},{"y":2015,"o":10,"s":"∫_(-π/2)^(π/2)l((sin x)/(1+cos x)+|x|r)dx = ＿＿＿","a":"π²/4。"},{"y":2022,"o":12,"s":"∫₁^(e²)(ln x)/(√(x)) dx = ＿＿＿","a":"4。"},{"y":2023,"o":14,"s":"设连续函数 f(x) 满足 f(x+2)-f(x) = x，∫₀² f(x) dx = 0，则 ∫₁³ f(x) dx = ＿＿＿","a":"frac12。"},{"y":2025,"o":17,"s":"计算 ∫₀¹1/((x+1)(x²-2x+2)) dx。","a":"(3ln2+π)/10。"}],"Keac5b4d1|1":[{"y":2009,"o":3,"s":"设函数 y = f(x) 在区间 [-1,3] 上的图形如图所示，则函数 F(x) = ∫₀ˣf(t) dt 的图形为（ ）题图中的 f(x)：在 [-1,0) 上为水平线段 f(x) = 1（x = 0 处为空心点）；在 (0,2) 上为一段自 (0,-1) 上升、经过 (1,0)、到 (2,2) 的曲线（x = 2 处为空心点）；在 (2,3] 上 f(x) = 0。四个选项均为 F(x) 的图形，差异集中在 F(-1)、F(0) 的取值、x = 2 处是否连续以及 [2,3] 段是否水平：(A) F(-1) > 0，F(0) = 0，先减后增，[2,3] 上为水平线段；(B) 过原点且 F(-1) < 0，但在 x = 2 处断开（不连续），[2,3] 上仍上升；(C) F(-1) = 0，F(0) = 1，先减后增，[2,3] 上为水平线段；(D) 处处连续，F(-1) = -1，F(0) = 0，在 [-1,1] 上 F(x) ≤0，x = 1 取极小值，(1,2) 上单调增加，[2,3] 上为水平线段。","a":"D。"},{"y":2024,"o":1,"s":"已知函数 f(x) = ∫₀ˣe^(cos t) dt，g(x) = ∫₀^(sin x)e^(t²) dt，则（ ）(A) f(x) 是奇函数，g(x) 是偶函数(B) f(x) 是偶函数，g(x) 是奇函数(C) f(x) 与 g(x) 均为奇函数(D) f(x) 与 g(x) 均为周期函数","a":"C。"}],"Kfd2f9e37|1":[{"y":2010,"o":3,"s":"设 m,n 均是正整数，则反常积分∫₀¹(sqrt[m]ln²(1-x))/(sqrt[n]x) dx的收敛性（ ）(A) 仅与 m 的取值有关(B) 仅与 n 的取值有关(C) 与 m,n 的取值都有关(D) 与 m,n 的取值都无关","a":"D。"},{"y":2013,"o":12,"s":"∫₁^(+∞)(ln x)/((1+x)²) dx = underline .","a":"ln 2。"},{"y":2016,"o":1,"s":"若反常积分∫₀^(+∞)1/(xᵃ(1+x)ᵇ) dx收敛，则（ ）(A) a < 1 且 b > 1(B) a > 1 且 b > 1(C) a < 1 且 a+b > 1(D) a > 1 且 a+b > 1","a":"C。"},{"y":2021,"o":11,"s":"∫₀^(+∞)1/(x²+2x+2) dx = underline .","a":"π/4。"},{"y":2026,"o":14,"s":"设∫₁^(+∞)(ln(x+1))/x² dx = underline .","a":"2ln 2。"}],"Kb8203539|1":[{"y":2009,"o":17,"s":"椭球面 S₁ 是椭圆 x²/4+y²/3 = 1 绕 x 轴旋转而成，圆锥面 S₂ 是由过点 (4,0) 且与椭圆 x²/4+y²/3 = 1 相切的直线绕 x 轴旋转而成。I. 求 S₁ 及 S₂ 的方程；II. 求 S₁ 与 S₂ 之间的立体的体积。","a":"I. S₁:x²/4+(y²+z²)/3 = 1，S₂:y²+z² = frac14(x-4)²；II. V = π。"},{"y":2011,"o":9,"s":"曲线 y = ∫₀ˣtan t dt (0 ≤ x ≤ π/4) 的弧长 s = underline 。","a":"ln(sqrt2+1)。"},{"y":2012,"o":18,"s":"求曲线 y = e⁻ˣsin x (x ≥0) 与 x 轴之间图形的面积。x = f(t), y = cos t给出，其中 0 ≤ t < π/2，函数 f(t) 具有连续导数，且 f(0) = 0，f'(t) > 0 (0 < t < π/2)。若曲线 L 的切线与 x 轴的交点到切点的距离恒为 1，求函数 f(t) 的表达式，并求以曲线 L 及 x 轴和 y 轴为边界的区域的面积。","a":"f(t) = ln|sec t+tan t|-sin t (0 ≤ t < π/2)，面积 S = π/4。"},{"y":2017,"o":4,"s":"甲、乙两人赛跑，计时开始时，甲在乙前方 10（单位：m）处，图中，实线表示甲的速度曲线 v = v₁(t)（单位：m/s），虚线表示乙的速度曲线 v = v₂(t)，三块阴影部分面积的数值依次是 10, 20, 3。计时开始后乙追上甲的时刻记为 t₀（单位：s），则（ ）(A) t₀ = 10(B) 15 < t₀ < 20(C) t₀ = 25(D) t₀ > 25图中横轴为 t(s)，刻度 0,5,10,15,20,25,30；三块阴影分别落在 0 到 10、10 到 25、25 到 30 之间。","a":"C。"},{"y":2019,"o":17,"s":"求曲线 y = e⁻ˣsin x (x ≥0) 与 x 轴之间图形的面积。","a":"frac12+1/(e^π-1)（即 (e^π+1)/(2(e^π-1))）。"}],"K7d287abb|1":[{"y":2009,"o":9,"s":"设函数 f(u,v) 具有二阶连续偏导数，z = f(x,xy)，则 (∂² z)/(∂ x∂ y) = underline。","a":"x f₁₂''(x,xy)+f₂'(x,xy)+xy f₂₂''(x,xy)。"},{"y":2010,"o":2,"s":"设函数 z = z(x,y) 由方程 F(y/x,z/x) = 0 确定，其中 F 为可微函数，且 F₂' ≠0，则 x(∂ z)/(∂ x)+y(∂ z)/(∂ y) = （ ）(A) x(B) z(C) -x(D) -z","a":"B。"},{"y":2011,"o":11,"s":"设函数 F(x,y) = ∫₀ˣʸ(sin t)/(1+t²) dt，则 .(∂² F)/(∂ x²)|_(x = 0, y = 2) = underline。","a":"4。"},{"y":2011,"o":16,"s":"设函数 z = f(xy,yg(x))，其中函数 f 具有二阶连续偏导数，函数 g(x) 可导，且在 x = 1 处取得极值 g(1) = 1。求 .(∂² z)/(∂ x∂ y)|_(x = 1, y = 1)。","a":"f₁'(1,1)+f₁₁''(1,1)+f₁₂''(1,1)。"},{"y":2017,"o":15,"s":"设函数 f(u,v) 具有 2 阶连续偏导数，y = f(eˣ,cos x)，求 .dy/dx|ₓ₌₀，.d²y/dx²|ₓ₌₀。","a":".dy/dx|ₓ₌₀ = f₁'(1,1)；.d²y/dx²|ₓ₌₀ = f₁'(1,1)+f₁₁''(1,1)-f₂'(1,1)。"},{"y":2019,"o":9,"s":"设函数 f(u) 可导，z = f(sin y-sin x)+xy，则 1/(cos x)·(∂ z)/(∂ x)+1/(cos y)·(∂ z)/(∂ y) = underline。","a":"y/(cos x)+x/(cos y)。"},{"y":2020,"o":12,"s":"设函数 f(x,y) = ∫₀ˣʸe^(xt²) dt，则 .(∂² f)/(∂ x∂ y)|_(1,1) = underline。","a":"4e。"},{"y":2022,"o":2,"s":"设函数 z = xy f(dfracyx)，其中 f(u) 可导，若 x(∂ z)/(∂ x)+y(∂ z)/(∂ y) = y²(ln y-ln x)，则（ ）(A) f(1) = dfrac12, f'(1) = 0(B) f(1) = 0, f'(1) = dfrac12(C) f(1) = dfrac12, f'(1) = 1(D) f(1) = 0, f'(1) = 1","a":"B。"},{"y":2024,"o":12,"s":"设函数 f(u,v) 具有 2 阶连续偏导数，且 .df|_(1,1) = 3 du+4 dv。令 y = f(cos x,1+x²)，则 .d²y/dx²|ₓ₌₀ = underline。","a":"5。"},{"y":2026,"o":1,"s":"设函数 z = z(x,y) 由方程 x-az = eʸ⁺ᵃᶻ（a 是非 0 常数）确定，则（ ）(A) (∂ z)/(∂ x)-(∂ z)/(∂ y) = dfrac1a(B) (∂ z)/(∂ x)+(∂ z)/(∂ y) = dfrac1a(C) (∂ z)/(∂ x)-(∂ z)/(∂ y) = -dfrac1a(D) (∂ z)/(∂ x)+(∂ z)/(∂ y) = -dfrac1a","a":"A。"},{"y":2026,"o":11,"s":"设向量 vecv₁ = (0,x,z)，vecv₂ = (y,0,1)，令 vecF(x,y,z) = vecv₁×vecv₂，则 div vecF = underline。","a":"1+z。"}],"K0bf92dbd|1":[{"y":2012,"o":3,"s":"如果函数 f(x,y) 在点 (0,0) 处连续，那么下列命题正确的是（ ）(A) 若极限 lim_(x,y) → (0,0)(f(x,y))/(|x|+|y|) 存在，则 f(x,y) 在点 (0,0) 处可微(B) 若极限 lim_(x,y) → (0,0)(f(x,y))/(x²+y²) 存在，则 f(x,y) 在点 (0,0) 处可微(C) 若 f(x,y) 在点 (0,0) 处可微，则极限 lim_(x,y) → (0,0)(f(x,y))/(|x|+|y|) 存在(D) 若 f(x,y) 在点 (0,0) 处可微，则极限 lim_(x,y) → (0,0)(f(x,y))/(x²+y²) 存在","a":"B。"},{"y":2015,"o":11,"s":"若函数 z = z(x,y) 由方程 eᶻ+xyz+x+cos x = 2 确定，则 .dz|_(0,1) = underline。","a":"-dx。"},{"y":2016,"o":11,"s":"设函数 f(u,v) 可微，z = z(x,y) 由方程 (x+1)z-y² = x² f(x-z,y) 确定，则 .dz|_(0,1) = underline。","a":"-dx+2dy。"},{"y":2020,"o":3,"s":"设函数 f(x,y) 在点 (0,0) 处可微，f(0,0) = 0，vecn = .((∂ f)/(∂ x),(∂ f)/(∂ y),-1)|_(0,0)，非零向量 vecα 与 vecn 垂直，则（ ）(A) lim_(x,y) → (0,0)(l|vecn·(x,y,f(x,y))r|)/(√(x²+y²)) 存在(B) lim_(x,y) → (0,0)(l|vecn×(x,y,f(x,y))r|)/(√(x²+y²)) 存在(C) lim_(x,y) → (0,0)(l|vecα·(x,y,f(x,y))r|)/(√(x²+y²)) 存在(D) lim_(x,y) → (0,0)(l|vecα×(x,y,f(x,y))r|)/(√(x²+y²)) 存在","a":"A。"},{"y":2021,"o":2,"s":"设函数 f(x,y) 可微，且 f(x+1,eˣ) = x(x+1)²，f(x,x²) = 2x²ln x，则 df(1,1) = （ ）(A) dx+dy(B) dx-dy(C) dy(D) -dy","a":"C。"},{"y":2026,"o":18,"s":"设 f(u) 在 (0,+∞) 内具有 3 阶连续导数，且存在可微函数 F(x,y) 使dF(x,y) = (f(xy))/x²y dx+(f''(xy))/xy² dy (xy > 0).(1) 证明：(f''(u))/u-(f(u))/u = c，c 为常数；(2) 设 f(1) = 1，f'(1) = -1，f''(1) = 0，求 f(u) 的表达式。","a":"第 (1) 问 c 为常数（由混合偏导相等证得）；第 (2) 问 c = -1，f(u) = e¹⁻ᵘ-eᵘ⁻¹+u。"}],"K21f808c5|1":[{"y":2013,"o":2,"s":"曲面 x²+cos(xy)+yz+x = 0 在点 (0,1,-1) 处的切平面方程为（ ）(A) x-y+z = -2(B) x+y+z = 0(C) x-2y+z = -3(D) x-y-z = 0","a":"A。"},{"y":2014,"o":9,"s":"曲面 z = x²(1-sin y)+y²(1-sin x) 在点 (1,0,1) 处的切平面方程为 ______","a":"2x-y-z-1 = 0（即 2x-y-z = 1）。"},{"y":2018,"o":2,"s":"过点 (1,0,0)，(0,1,0)，且与曲面 z = x²+y² 相切的平面为（ ）(A) z = 0 与 x+y-z = 1(B) z = 0 与 2x+2y-z = 2(C) x = y 与 x+y-z = 1(D) x = y 与 2x+2y-z = 2","a":"B。"},{"y":2023,"o":12,"s":"曲面 z = x+2y+ln(1+x²+y²) 在点 (0,0,0) 处的切平面方程为 ______","a":"x+2y-z = 0。"}],"K3ed658fc|1":[{"y":2012,"o":11,"s":".grad(xy+z/y)|_(2,1,1) = ______","a":"boldsymboli+boldsymbolj+boldsymbolk（即 (1,1,1)）。"},{"y":2017,"o":3,"s":"函数 f(x,y,z) = x²y+z² 在点 (1,2,0) 处沿向量 boldsymboln = (1,2,2) 的方向导数为（ ）(A) 12(B) 6(C) 4(D) 2","a":"D。"},{"y":2019,"o":16,"s":"设 a,b 为实数，函数 z = 2+ax²+by² 在点 (3,4) 处的方向导数中，沿方向 boldsymboll = -3boldsymboli-4boldsymbolj 的方向导数最大，最大值为 10。I. 求 a,b；II. 求曲面 z = 2+ax²+by² (z ≥0) 的面积。","a":"第 I 问 a = b = -1；第 II 问曲面面积为 13π/3。"},{"y":2022,"o":11,"s":"函数 f(x,y) = x²+2y² 在点 (0,1) 处的最大方向导数为 ______","a":"4。"},{"y":2025,"o":13,"s":"已知函数 u(x,y,z) = xy²z³，向量 boldsymboln = (2,2,-1)，则 .(∂ u)/(∂ boldsymboln)|_(1,1,1) = ______","a":"1。"}],"Kce32dc73|1":[{"y":2009,"o":15,"s":"求二元函数 f(x,y) = x²(2+y²)+yln y 的极值。","a":"在 (0,frac1e) 处取得极小值 -frac1e，无极大值。"},{"y":2011,"o":3,"s":"设函数 f(x) 具有二阶连续导数，且 f(x) > 0，f'(0) = 0，则函数 z = f(x)ln f(y) 在点 (0,0) 处取得极小值的一个充分条件是（ ）(A) f(0) > 1, f''(0) > 0(B) f(0) > 1, f''(0) < 0(C) f(0) < 1, f''(0) > 0(D) f(0) < 1, f''(0) < 0","a":"A。"},{"y":2012,"o":16,"s":"求函数 f(x,y) = xe^(-(x²+y²)/2) 的极值。","a":"极大值 e^(-frac12)（在 (1,0) 处），极小值 -e^(-frac12)（在 (-1,0) 处）。"},{"y":2013,"o":17,"s":"求函数 f(x,y) = l(y+x³/3r)eˣ⁺ʸ 的极值。","a":"在 (1,-frac43) 处取得极小值 -e^(-frac13)，无极大值。"},{"y":2015,"o":17,"s":"已知函数 f(x,y) = x+y+xy，曲线 C:x²+y²+xy = 3，求 f(x,y) 在曲线 C 上的最大方向导数。","a":"3。"},{"y":2018,"o":16,"s":"将长为 2m 的铁丝分成三段，依次围成圆、正方形与正三角形。三个图形的面积之和是否存在最小值？若存在，求出最小值。","a":"存在，最小值为 1/(π+4+3sqrt3)。"},{"y":2020,"o":15,"s":"求函数 f(x,y) = x³+8y³-xy 的极值。","a":"在 (frac16,1/12) 处取得极小值 -1/216，无极大值。"},{"y":2021,"o":19,"s":"已知曲线 C：x²+2y²-z = 6, 4x+2y+z = 30,求 C 上的点到 xOy 坐标面距离的最大值。","a":"66，在点 (-8,-2,66) 处取得。"},{"y":2022,"o":13,"s":"当 x ≥0, y ≥0 时，x²+y² ≤ keˣ⁺ʸ 恒成立，则 k 的取值范围是 ______。","a":"[4e⁻²,+∞)，即 k ≥4e⁻²。"},{"y":2023,"o":18,"s":"求函数 f(x,y) = (y-x²)(y-x³) 的极值。","a":"在 (frac23,10/27) 处取得极小值 -4/729，无极大值。"},{"y":2024,"o":18,"s":"已知函数 f(x,y) = x³+y³-(x+y)²+3，设 T 是曲面 z = f(x,y) 在点 (1,1,1) 处的切平面，D 为 T 与坐标平面所围成的有界区域在 xOy 面上的投影。I. 求 T 的方程；II. 求 f(x,y) 在 D 上的最大值和最小值。","a":"I. x+y+z = 3；II. 最大值 21，最小值 17/27。"},{"y":2026,"o":17,"s":"求 f(x,y) = (2x²-y²)eˣ 的极值。","a":"在 (-2,0) 处取得极大值 8e⁻²，无极小值。"}],"Kd973398e|1":[{"y":2009,"o":2,"s":"如图，正方形 {(x,y)mid |x| ≤1, |y| ≤1} 被其对角线划分为四个区域 Dₖ (k = 1,2,3,4)，Iₖ = ∬_(Dₖ) ycos x dx dy ,则 max_(1 ≤ k ≤4){Iₖ} = ()。（图：以原点 O 为中心、边长 2 的正方形，坐标轴 x、y 刻度均为 -1,0,1；两条对角线把正方形分成四个全等的等腰直角三角形，上方区域记为 D₁，左方为 D₂，下方为 D₃，右方为 D₄。）(A) I₁(B) I₂(C) I₃(D) I₄","a":"A。"},{"y":2010,"o":4,"s":"lim_(n → ∞)∑_(i = 1)ⁿ∑_(j = 1)ⁿn/((n+i)(n²+j²)) = ()(A) ∫₀¹dx∫₀ˣ1/((1+x)(1+y²)) dy(B) ∫₀¹dx∫₀ˣ1/((1+x)(1+y)) dy(C) ∫₀¹dx∫₀¹1/((1+x)(1+y)) dy(D) ∫₀¹dx∫₀¹1/((1+x)(1+y²)) dy","a":"D。"}],"Kb48cd5a2|1":[{"y":2014,"o":3,"s":"设 f(x,y) 是连续函数，则∫₀¹ dy∫_(-√(1-y²))¹⁻ʸ f(x,y) dx = ()(A) ∫₀¹ dx∫ₓ₋₁⁰ f(x,y) dy+∫₋₁⁰ dx∫₀^(√(1-x²)) f(x,y) dy(B) ∫₀¹ dx∫₁₋ₓ⁰ f(x,y) dy+∫₋₁⁰ dx∫_(-√(1-x²))⁰ f(x,y) dy(C) ∫₀^(π/2) dθ∫₀^(1/(cosθ+sinθ)) f(rcosθ,rsinθ) dr+∫_(π/2)^π dθ∫₀¹ f(rcosθ,rsinθ) dr(D) di","a":"D。"},{"y":2015,"o":4,"s":"设 D 是第一象限中的曲线 2xy = 1、4xy = 1 与直线 y = x、y = sqrt3 x 围成的平面区域，函数 f(x,y) 在 D 上连续，则∬_D f(x,y) dxdy = ()(A) ∫_(π/4)^(π/3) dθ∫_(2sin 2θ)^(1/(sin 2θ)) f(rcosθ,rsinθ) r dr(B) ∫_(π/4)^(π/3) dθ∫_(1/(√(2sin 2θ)))^(1/(√(sin 2θ))) f(rcosθ,rsinθ) r dr(C) ∫_(π/4)^(π/3) dθ∫_(2sin 2θ)^(1/(sin 2θ)) f(rcosθ,rsinθ)","a":"B。"},{"y":2025,"o":4,"s":"设函数 f(x,y) 连续，则∫₋₂² dx∫_(4-x²)⁴ f(x,y) dy = ()(A) ∫₀⁴[∫₋₂^(-√(4-y)) f(x,y) dx+∫_(√(4-y))² f(x,y) dx]dy(B) ∫₀⁴[∫₋₂^(√(4-y)) f(x,y) dx+∫_(√(4-y))² f(x,y) dx]dy(C) ∫₀⁴[∫₋₂^(-√(4-y)) f(x,y) dx+∫₂^(√(4-y)) f(x,y) dx]dy(D) 2∫₀⁴ dy∫_(√(4-y))² f(x,y) dx","a":"A。"}],"Ka9a19c53|1":[{"y":2009,"o":12,"s":"设 Ω = {(x,y,z)mid x²+y²+z² ≤1}，则 ∭_Ω z² dx dy dz = underline。","a":"4π/15。"},{"y":2011,"o":19,"s":"已知函数 f(x,y) 具有二阶连续偏导数，且 f(1,y) = 0，f(x,1) = 0，∬_D f(x,y) dx dy = a，其中 D = {(x,y)mid 0 ≤ x ≤1, 0 ≤ y ≤1}，计算二重积分 I = ∬_D xy f''_(xy)(x,y) dx dy。","a":"a。"},{"y":2015,"o":12,"s":"设 Ω 是由平面 x+y+z = 1 与三个坐标平面所围成的空间区域，则 ∭_Ω (x+2y+3z) dx dy dz = underline。","a":"dfrac14。"},{"y":2016,"o":15,"s":"已知平面区域 D = {(r,θ)mid 2 ≤ r ≤2(1+cosθ), -π/2 ≤ θ ≤ π/2}，计算二重积分 ∬_D x dx dy。","a":"5π+32/3。"},{"y":2022,"o":18,"s":"已知平面区域 D = {(x,y)mid y-2 ≤ x ≤ √(4-y²), 0 ≤ y ≤2}，计算 I = ∬_D((x-y)²)/(x²+y²) dx dy。","a":"2π-2。"},{"y":2024,"o":17,"s":"已知平面区域 D = {(x,y)mid √(1-y²) ≤ x ≤1, -1 ≤ y ≤1}，计算 ∬_Dx/(√(x²+y²)) dx dy。","a":"ln(sqrt2+1)+sqrt2-2。"},{"y":2026,"o":4,"s":"已知有界区域 Ω 由曲面 z = √(4-x²-y²) 与 z = √(x²+y²) 围成，函数 f(u) 连续，则∭_Ω f(x²+y²+z²) dx dy dz = ()(A) ∫₀^(2π)dθ∫₀² dr∫_r^(√(4-r²)) f(r²+z²) r dz(B) ∫₀^(2π)dθ∫₀^(sqrt2) dr∫₀^(√(4-r²)) f(r²+z²) r dz(C) ∫₀^(2π)dθ∫₀^(π/4)dφ∫₀² f(r²) r²sinφ dr(D) ∫₀^(2π)dθ∫₀^(π/2)dφ∫₀² f(r²) r²sinφ dr","a":"C。"}],"Kcd78f4fd|1":[{"y":2010,"o":12,"s":"设 Ω = {(x,y,z)mid x²+y² ≤ z ≤1}，则 Ω 的形心的竖坐标 barz = underline。","a":"dfrac23。"},{"y":2013,"o":19,"s":"设直线 L 过 A(1,0,0)、B(0,1,1) 两点，将 L 绕 z 轴旋转一周得到曲面 Σ，Σ 与平面 z = 0、z = 2 所围成的立体为 Ω。Ⅰ. 求曲面 Σ 的方程；Ⅱ. 求 Ω 的形心坐标。","a":"Ⅰ. x²+y² = 2z²-2z+1；Ⅱ. (0,0,dfrac75)。"},{"y":2019,"o":19,"s":"设 Ω 是由锥面 x²+(y-z)² = (1-z)²（0 ≤ z ≤1）与平面 z = 0 围成的锥体，求 Ω 的形心坐标。","a":"(0,dfrac14,dfrac14)。"}],"K09f6d2d7|1":[{"y":2009,"o":11,"s":"已知曲线 L:y = x² (0 ≤ x ≤ sqrt2)，则 ∫_L x ds = underline。","a":"13/6。"},{"y":2018,"o":12,"s":"设 L 为球面 x²+y²+z² = 1 与平面 x+y+z = 0 的交线，则 ∮_L xy ds = underline。","a":"-π/3。"}],"K2b3edfd3|1":[{"y":2010,"o":11,"s":"已知曲线 L 的方程为 y = 1-|x|，x∈[-1,1]，起点是 (-1,0)，终点为 (1,0)，则曲线积分 ∫_L xy dx+x² dy = underline。","a":"0。"},{"y":2011,"o":12,"s":"设 L 是柱面 x²+y² = 1 与平面 z = x+y 的交线，从 z 轴正向往 z 轴负向看去为逆时针方向，则曲线积分 ∮_L xz dx+x dy+y²/2 dz = underline。","a":"π。"},{"y":2012,"o":19,"s":"已知 L 是第一象限中从点 (0,0) 沿圆周 x²+y² = 2x 到点 (2,0)，再沿圆周 x²+y² = 4 到点 (0,2) 的曲线段，计算曲线积分I = ∫_L 3x²y dx+(x³+x-2y) dy .","a":"π/2-4。"},{"y":2013,"o":4,"s":"设 L₁:x²+y² = 1，L₂:x²+y² = 2，L₃:x²+2y² = 2，L₄:2x²+y² = 2 为四条逆时针方向的平面曲线。记I_i = ∮_(L_i)(y+y³/6)dx+(2x-x³/3)dy(i = 1,2,3,4),则 max{I₁,I₂,I₃,I₄} = （ ）(A) I₁(B) I₂(C) I₃(D) I₄","a":"D。"},{"y":2014,"o":12,"s":"设 L 是柱面 x²+y² = 1 与平面 y+z = 0 的交线，从 z 轴正向往 z 轴负向看去为逆时针方向，则曲线积分 ∮_L z dx+y dz = underline。","a":"π。"},{"y":2015,"o":19,"s":"已知曲线 L 的方程为 z = √(2-x²-y²) 与 z = x 联立，起点为 A(0,sqrt2,0)，终点为 B(0,-sqrt2,0)，计算曲线积分I = ∫_L(y+z) dx+(z²-x²+y) dy+x²y² dz .","a":"(sqrt2)/2π。"},{"y":2016,"o":17,"s":"设函数 f(x,y) 满足 (∂ f(x,y))/(∂ x) = (2x+1)e²ˣ⁻ʸ，且 f(0,y) = y+1，Lₜ 是从点 (0,0) 到点 (1,t) 的光滑曲线。计算曲线积分I(t) = ∫_(Lₜ)(∂ f(x,y))/(∂ x) dx+(∂ f(x,y))/(∂ y) dy,并求 I(t) 的最小值。","a":"I(t) = e²⁻ᵗ+t；当 t = 2 时取最小值 3。"},{"y":2017,"o":11,"s":"若曲线积分 ∫_L(x dx-ay dy)/(x²+y²-1) 在区域 D = {(x,y):x²+y² < 1} 内与路径无关，则 a = underline。","a":"a = -1。"},{"y":2019,"o":4,"s":"设函数 Q(x,y) = x/y²。如果对上半平面 y > 0 内的任意有向光滑封闭曲线 C 都有 ∮_C P(x,y) dx+Q(x,y) dy = 0，那么函数 P(x,y) 可取为（ ）(A) y-x²/y³(B) dfrac1y-x²/y³(C) dfrac1x-dfrac1y(D) x-dfrac1y","a":"D。"},{"y":2020,"o":16,"s":"计算曲线积分I = ∮_L(4x-y)/(4x²+y²) dx+(x+y)/(4x²+y²) dy,其中 L 为 x²+y² = 2，方向为逆时针方向。","a":"π。"},{"y":2021,"o":20,"s":"设 D⊂R² 是有界单连通闭区域，I(D) = ∬_D(4-x²-y²) dxdy 取得最大值的积分区域为 D₁。I. 求 I(D₁) 的值；II. 计算 ∫_(∂ D₁)((xe^(x²+4y²)+y) dx+(4ye^(x²+4y²)-x) dy)/(x²+4y²)，其中 ∂ D₁ 是 D₁ 的正向边界。","a":"I. 8π；II. -π。"},{"y":2022,"o":19,"s":"已知曲线 L 是曲面 Σ:4x²+y²+z² = 1，x ≥0、y ≥0、z ≥0 的边界，曲面 Σ 方向朝上，曲线 L 的方向和曲面 Σ 的方向符合右手法则，计算I = ∮_L(yz²-cos z) dx+2xz² dy+(2xyz+xsin z) dz .","a":"0。"},{"y":2024,"o":20,"s":"已知有向曲线 L 为球面 x²+y²+z² = 2x 与平面 2x-z-1 = 0 的交线，从 z 轴正向往 z 轴负向看去为逆时针方向，计算曲线积分∫_L(6xyz-yz²) dx+2x²z dy+xyz dz .","a":"(4sqrt5π)/25。"},{"y":2025,"o":14,"s":"已知有向曲线 L 是沿抛物线 y = 1-x² 从点 (1,0) 到点 (-1,0) 的一段，则曲线积分 ∫_L(y+cos x) dx+(2x+cos y) dy = underline。","a":"dfrac43-2sin1。"},{"y":2026,"o":19,"s":"设有向曲线 L 为椭圆 x²+3y² = 1 上沿逆时针方向从点 A(-frac12,-frac12) 到点 B(frac12,frac12) 的部分，计算曲线积分I = ∫_L(e^(x²)sin x-2xy)dx+(6x-x²-ycos⁴y)dy .","a":"sqrt3π-dfrac14。"}],"Kfe98dba7|1":[{"y":2010,"o":19,"s":"设 P 为椭球面 S: x²+y²+z²-yz = 1 上的动点，若 S 在点 P 处的切平面与 xOy 面垂直，求点 P 的轨迹 C，并计算曲面积分I = ∬_Σ((x+sqrt3)|y-2z|)/(√(4+y²+z²-4yz)) dS,其中 Σ 是椭球面 S 位于曲线 C 上方的部分。","a":"C 为 x²+frac34y² = 1 与 y = 2z 的交线；I = 2π。"},{"y":2012,"o":12,"s":"设 Σ = {(x,y,z)mid x+y+z = 1, x ≥0, y ≥0, z ≥0}，则 ∬_Σ y² dS = underline。","a":"(sqrt3)/12。"},{"y":2017,"o":19,"s":"设薄片型物体 S 是圆锥面 z = √(x²+y²) 被柱面 z² = 2x 割下的有限部分，其上任一点的密度为 μ(x,y,z) = 9√(x²+y²+z²)。记圆锥面与柱面的交线为 C。I. 求 C 在 xOy 平面上的投影曲线的方程；II. 求 S 的质量 M。","a":"I. 投影曲线为 x²+y² = 2x 且 z = 0；II. M = 64。"}],"K1638b24b|1":[{"y":2009,"o":19,"s":"计算曲面积分I = ∬_Σ(x dydz+y dzdx+z dxdy)/((x²+y²+z²)^(frac32)),其中 Σ 是曲面 2x²+2y²+z² = 4 的外侧。","a":"I = 4π。"},{"y":2014,"o":18,"s":"设 Σ 为曲面 z = x²+y²（z ≤1）的上侧，计算曲面积分I = ∬_Σ (x-1)³ dydz+(y-1)³ dzdx+(z-1) dxdy .","a":"I = -4π。"},{"y":2016,"o":18,"s":"设有界区域 Ω 由平面 2x+y+2z = 2 与三个坐标平面围成，Σ 为 Ω 整个表面的外侧，计算曲面积分I = ∬_Σ (x²+1) dydz-2y dzdx+3z dxdy .","a":"I = dfrac12。"},{"y":2018,"o":17,"s":"设 Σ 是曲面 x = √(1-3y²-3z²) 的前侧，计算曲面积分I = ∬_Σ x dydz+(y³+2) dzdx+z³ dxdy .","a":"I = 14π/45。"},{"y":2019,"o":12,"s":"设 Σ 为曲面 x²+y²+4z² = 4（z ≥0）的上侧，则∬_Σ√(4-x²-4z²) dxdy = underline.","a":"32/3。"},{"y":2020,"o":18,"s":"设 Σ 为曲面 z = √(x²+y²)（1 ≤ x²+y² ≤4）的下侧，f(x) 是连续函数，计算I = ∬_Σ[xf(xy)+2x-y]dydz+[yf(xy)+2y+x]dzdx+[zf(xy)+z]dxdy .","a":"I = 14π/3。"},{"y":2021,"o":14,"s":"设 Σ 为空间区域 {(x,y,z)mid x²+4y² ≤4, 0 ≤ z ≤2} 表面的外侧，则曲面积分∬_Σ x² dydz+y² dzdx+z dxdy = underline.","a":"4π。"},{"y":2023,"o":19,"s":"设空间有界区域 Ω 由柱面 x²+y² = 1 与平面 z = 0 和 x+z = 1 围成，Σ 为 Ω 边界曲面的外侧，计算曲面积分I = ∬_Σ 2xz dydz+xzcos y dzdx+3yzsin x dxdy .","a":"I = 5π/4。"},{"y":2024,"o":2,"s":"设 P = P(x,y,z)、Q = Q(x,y,z) 均为连续函数，Σ 为曲面 z = √(1-x²-y²)（x ≤0、y ≥0）的上侧，则 ∬_Σ P dydz+Q dzdx = （ ）(A) ∬_Σ(fracxzP+fracyzQ)dxdy(B) ∬_Σ(-fracxzP+fracyzQ)dxdy(C) ∬_Σ(fracxzP-fracyzQ)dxdy(D) ∬_Σ(-fracxzP-fracyzQ)dxdy","a":"A。"},{"y":2025,"o":20,"s":"设 Σ 是由直线 x = 0、y = 0 绕直线 x = t、y = t、z = t（t 为参数）旋转一周得到的曲面，Σ₁ 是 Σ 介于平面 x+y+z = 0 与平面 x+y+z = 1 之间部分的外侧，计算曲面积分I = ∬_(Σ₁)x dydz+(y+1) dzdx+(z+2) dxdy .","a":"I = -(2sqrt3π)/3。"}],"Kd2ac6d62|1":[{"y":2016,"o":10,"s":"设向量场 vecA(x,y,z) = (x+y+z) veci+xy vecj+z veck，则旋度 rot vecA = underline。","a":"vecj+(y-1) veck。"},{"y":2018,"o":11,"s":"设 vecF(x,y,z) = xy veci-yz vecj+zx veck，则 rot vecF(1,1,0) = underline。","a":"veci-veck。"}],"K91873e3c|1":[{"y":2009,"o":4,"s":"设有两个数列 {aₙ}，{bₙ}，若 lim_(n → ∞)aₙ = 0，则（ ）(A) 当 ∑ₙ₌₁^∞bₙ 收敛时，∑ₙ₌₁^∞aₙbₙ 收敛(B) 当 ∑ₙ₌₁^∞bₙ 发散时，∑ₙ₌₁^∞aₙbₙ 发散(C) 当 ∑ₙ₌₁^∞|bₙ| 收敛时，∑ₙ₌₁^∞aₙ²bₙ² 收敛(D) 当 ∑ₙ₌₁^∞|bₙ| 发散时，∑ₙ₌₁^∞aₙ²bₙ² 发散","a":"C。"},{"y":2014,"o":19,"s":"设数列 {aₙ}，{bₙ} 满足 0 < aₙ < π/2，0 < bₙ < π/2，cos aₙ-aₙ = cos bₙ，且级数 ∑ₙ₌₁^∞bₙ 收敛。(I) 证明 lim_(n → ∞)aₙ = 0；(II) 证明级数 ∑ₙ₌₁^∞aₙ/bₙ 收敛。","a":"两问均获证。"},{"y":2016,"o":19,"s":"已知函数 f(x) 可导，且 f(0) = 1，0 < f'(x) < dfrac12。设数列 {xₙ} 满足 xₙ₊₁ = f(xₙ)（n = 1,2,⋯）。证明：(I) 级数 ∑ₙ₌₁^∞(xₙ₊₁-xₙ) 绝对收敛；(II) lim_(n → ∞)xₙ 存在，且 0 < lim_(n → ∞)xₙ < 2。","a":"证明题（两问）。"},{"y":2019,"o":3,"s":"设 {uₙ} 是单调增加的有界数列，则下列级数中收敛的是（ ）(A) ∑ₙ₌₁^∞uₙ/n(B) ∑ₙ₌₁^∞(-1)ⁿ1/uₙ(C) ∑ₙ₌₁^∞(1-uₙ/(uₙ₊₁))(D) ∑ₙ₌₁^∞(uₙ₊₁²-uₙ²)","a":"D。"},{"y":2023,"o":4,"s":"已知 aₙ < bₙ（n = 1,2,⋯）。若级数 ∑ₙ₌₁^∞aₙ 与 ∑ₙ₌₁^∞bₙ 均收敛，则「∑ₙ₌₁^∞aₙ 绝对收敛」是「∑ₙ₌₁^∞bₙ 绝对收敛」的（ ）(A) 充分必要条件(B) 充分不必要条件(C) 必要不充分条件(D) 既不充分也不必要条件","a":"A。"},{"y":2025,"o":2,"s":"已知级数：① ∑ₙ₌₁^∞sinn³π/(n²+1)；② ∑ₙ₌₁^∞(-1)ⁿ(1/(sqrt[3]n²)-tan1/(sqrt[3]n²))，则（ ）(A) ①与②均条件收敛(B) ①条件收敛，②绝对收敛(C) ①绝对收敛，②条件收敛(D) ①与②均绝对收敛","a":"B。"}],"Kb0d920bf|1":[{"y":2011,"o":2,"s":"设数列 {aₙ} 单调减少，lim_(n → ∞)aₙ = 0，Sₙ = ∑ₖ₌₁ⁿaₖ（n = 1,2,⋯）无界，则幂级数 ∑ₙ₌₁^∞aₙ(x-1)ⁿ 的收敛域为（ ）(A) (-1,1](B) [-1,1)(C) [0,2)(D) (0,2]","a":"C。"},{"y":2015,"o":3,"s":"若级数 ∑ₙ₌₁^∞aₙ 条件收敛，则 x = sqrt3 与 x = 3 依次为幂级数 ∑ₙ₌₁^∞n aₙ(x-1)ⁿ 的（ ）(A) 收敛点，收敛点(B) 收敛点，发散点(C) 发散点，收敛点(D) 发散点，发散点","a":"B。"},{"y":2020,"o":4,"s":"设 R 为幂级数 ∑ₙ₌₁^∞aₙ xⁿ 的收敛半径，r 是实数，则（ ）(A) 当 ∑ₙ₌₁^∞a₂ₙr²ⁿ 发散时，|r| ≥ R(B) 当 ∑ₙ₌₁^∞a₂ₙr²ⁿ 收敛时，|r| ≤ R(C) 当 |r| ≥ R 时，∑ₙ₌₁^∞a₂ₙr²ⁿ 发散(D) 当 |r| ≤ R 时，∑ₙ₌₁^∞a₂ₙr²ⁿ 收敛","a":"A。"},{"y":2022,"o":14,"s":"已知级数 ∑ₙ₌₁^∞n!/nⁿe⁻ⁿˣ 的收敛域为 (a,+∞)，则 a = underline。","a":"-1。"},{"y":2026,"o":2,"s":"幂级数 ∑ₙ₌₁^∞((3+(-1)ⁿ)/4)ⁿx²ⁿ 的收敛域是（ ）(A) [-2,2](B) [-1,1](C) (-2,2)(D) (-1,1)","a":"D。"}],"K21ac2baa|1":[{"y":2009,"o":16,"s":"设 aₙ 为曲线 y = xⁿ 与 y = xⁿ⁺¹（n = 1,2,⋯）所围成区域的面积，记 S₁ = ∑ₙ₌₁^∞aₙ，S₂ = ∑ₙ₌₁^∞a₂ₙ₋₁，求 S₁ 与 S₂ 的值。","a":"S₁ = dfrac12，S₂ = 1-ln2。"},{"y":2010,"o":18,"s":"求幂级数 ∑ₙ₌₁^∞((-1)ⁿ⁻¹)/(2n-1)x²ⁿ 的收敛域及和函数。","a":"收敛域为 [-1,1]；和函数 S(x) = xarctan x（-1 ≤ x ≤1）。"},{"y":2012,"o":17,"s":"求幂级数 ∑ₙ₌₀^∞(4n²+4n+3)/(2n+1)x²ⁿ 的收敛域及和函数。","a":"收敛域为 (-1,1)；当 -1 < x < 1 且 x ≠0 时 S(x) = (1+x²)/((1-x²)²)+1/xln(1+x)/(1-x)，且 S(0) = 3。"},{"y":2013,"o":16,"s":"设数列 {aₙ} 满足条件：a₀ = 3，a₁ = 1，aₙ₋₂-n(n-1)aₙ = 0（n ≥2），S(x) 是幂级数 ∑ₙ₌₀^∞aₙxⁿ 的和函数。I. 证明 S''(x)-S(x) = 0；II. 求 S(x) 的表达式。","a":"I. 证明见"},{"y":2017,"o":12,"s":"幂级数 ∑ₙ₌₁^∞(-1)ⁿ⁻¹nxⁿ⁻¹ 在区间 (-1,1) 内的和函数 S(x) = underline。","a":"1/((1+x)²)。"},{"y":2018,"o":3,"s":"∑ₙ₌₀^∞(-1)ⁿ(2n+3)/((2n+1)!) = （ ）(A) sin1+cos1(B) 2sin1+cos1(C) 2sin1+2cos1(D) 2sin1+3cos1","a":"B。"},{"y":2019,"o":11,"s":"幂级数 ∑ₙ₌₀^∞((-1)ⁿ)/((2n)!)xⁿ 在 (0,+∞) 内的和函数 S(x) = underline。","a":"cos√(x)。"},{"y":2020,"o":17,"s":"设数列 {aₙ} 满足：a₁ = 1，(n+1)aₙ₊₁ = (n+dfrac12)aₙ，证明：当 |x| < 1 时，幂级数 ∑ₙ₌₁^∞aₙxⁿ 收敛，并求其和函数。","a":"收敛半径 R = 1，故 |x| < 1 时收敛；和函数 S(x) = 2/(√(1-x))-2（x∈(-1,1)）。"},{"y":2021,"o":18,"s":"设 uₙ(x) = e⁻ⁿˣ+(xⁿ⁺¹)/(n(n+1))（n = 1,2,⋯），求级数 ∑ₙ₌₁^∞uₙ(x) 的收敛域及和函数。","a":"收敛域为 [0,1]；当 x∈(0,1) 时 s(x) = 1/(eˣ-1)+(1-x)ln(1-x)+x，且 s(1) = e/(e-1)。"},{"y":2024,"o":3,"s":"已知幂级数 ∑ₙ₌₀^∞aₙxⁿ 的和函数为 ln(2+x)，则 ∑ₙ₌₀^∞na₂ₙ = （ ）(A) -dfrac16(B) -dfrac13(C) dfrac16(D) dfrac13","a":"A。"}],"K9c8780af|1":[{"y":2013,"o":3,"s":"设 f(x) = |x-dfrac12|，bₙ = 2∫₀¹ f(x)sin(nπ x) dx（n = 1,2,⋯）。令 S(x) = ∑ₙ₌₁^∞bₙsin(nπ x)，则 S(-dfrac94) = （ ）(A) dfrac34(B) dfrac14(C) -dfrac14(D) -dfrac34","a":"C。"},{"y":2023,"o":13,"s":"设 f(x) 为周期为 2 的周期函数，且 f(x) = 1-x，x∈[0,1]。若 f(x) = a₀/2+∑ₙ₌₁^∞aₙcos nπ x，则 ∑ₙ₌₁^∞a₂ₙ = underline。","a":"0。"},{"y":2024,"o":13,"s":"已知函数 f(x) = x+1。若 f(x) = a₀/2+∑ₙ₌₁^∞aₙcos nx，x∈[0,π]，则 lim_(n → ∞)n²sin a₂ₙ₋₁ = underline。","a":"-dfrac1π。"},{"y":2025,"o":12,"s":"已知函数 f(x) = 0（0 ≤ x < dfrac12），f(x) = x²（dfrac12 ≤ x ≤1）的傅里叶级数为 ∑ₙ₌₁^∞bₙsin nπ x，S(x) 为 ∑ₙ₌₁^∞bₙsin nπ x 的和函数，则 S(-dfrac72) = underline。","a":"dfrac18。"}],"K61b15cc0|2":[{"y":2011,"o":19,"s":"(I) 证明：对任意的正整数 n，都有 1/(n+1) < ln(1+dfrac1n) < dfrac1n 成立；(II) 设 aₙ = 1+dfrac12+⋯+dfrac1n-ln n (n = 1,2,⋯)，证明数列 {aₙ} 收敛。","a":"{aₙ} 收敛（其极限为欧拉常数 γ）。"},{"y":2012,"o":3,"s":"设 aₙ > 0 (n = 1,2,⋯)，Sₙ = a₁+a₂+⋯+aₙ，则数列 {Sₙ} 有界是数列 {aₙ} 收敛的（ ）(A) 充分必要条件 (B) 充分非必要条件 (C) 必要非充分条件 (D) 既非充分也非必要条件","a":"B。"},{"y":2013,"o":20,"s":"设函数 f(x) = ln x+dfrac1x。(I) 求 f(x) 的最小值；(II) 设数列 {xₙ} 满足 ln xₙ+1/(xₙ₊₁) < 1，证明 lim_(n → ∞)xₙ 存在，并求此极限。","a":"(I) 最小值 f(1) = 1；(II) lim xₙ = 1。"},{"y":2018,"o":21,"s":"设数列 {xₙ} 满足：x₁ > 0，xₙ e^(xₙ₊₁) = e^(xₙ)-1 (n = 1,2,⋯)。证明 {xₙ} 收敛，并求 lim_(n → ∞)xₙ。","a":"lim xₙ = 0。"},{"y":2022,"o":6,"s":"设数列 {xₙ} 满足 -π/2 ≤ xₙ ≤ π/2，则（ ）(A) 若 limcos(sin xₙ) 存在，则 lim xₙ 存在(B) 若 limsin(cos xₙ) 存在，则 lim xₙ 存在(C) 若 limcos(sin xₙ) 存在，则 limsin xₙ 存在，但 lim xₙ 不一定存在(D) 若 limsin(cos xₙ) 存在，则 limcos xₙ 存在，但 lim xₙ 不一定存在","a":"D。"},{"y":2024,"o":4,"s":"已知数列 {aₙ} (aₙ ≠0)，若 {aₙ} 发散，则（ ）(A) {aₙ+1/aₙ} 发散 (B) {aₙ-1/aₙ} 发散(C) {e^(aₙ)+1/(e^(aₙ))} 发散 (D) {e^(aₙ)-1/(e^(aₙ))} 发散","a":"D。"}],"Kc5c67202|2":[{"y":2009,"o":15,"s":"求极限 lim_(x → 0)((1-cos x)l[x-ln(1+tan x)r])/(sin⁴x)。","a":"dfrac14。"},{"y":2011,"o":9,"s":"lim_(x → 0)((1+2ˣ)/2)^(frac1x) = ________。","a":"sqrt2。"},{"y":2011,"o":15,"s":"已知函数 F(x) = (∫₀ˣln(1+t²) dt)/x^α。设 lim_(x → +∞)F(x) = lim_(x → 0⁺)F(x) = 0，试求 α 的取值范围。","a":"1 < α < 3。"},{"y":2013,"o":9,"s":"lim_(x → 0)[2-(ln(1+x))/x]^(frac1x) = ________。","a":"sqrte。"},{"y":2014,"o":5,"s":"设函数 f(x) = arctan x。若 f(x) = x f'(ξ)，则 lim_(x → 0)ξ²/x² = （ ）(A) 1 (B) dfrac23 (C) dfrac12 (D) dfrac13","a":"D，dfrac13。"},{"y":2014,"o":15,"s":"求极限 lim_(x → +∞)(∫₁ˣ[t²(e^(frac1t)-1)-t]dt)/(x²ln(1+frac1x))。","a":"dfrac12（与数学一 2014 第 15 题同题）。"},{"y":2016,"o":15,"s":"求极限 lim_(x → 0)(cos2x+2xsin x)^(1/x⁴)。","a":"e^(frac13)（与数学三 2016 第 15 题同题）。"},{"y":2017,"o":3,"s":"设数列 {xₙ} 收敛，则（ ）(A) 当 lim_(n → ∞)sin xₙ = 0 时，lim_(n → ∞)xₙ = 0(B) 当 lim_(n → ∞)(xₙ+√(|xₙ|)) = 0 时，lim_(n → ∞)xₙ = 0(C) 当 lim_(n → ∞)(xₙ+xₙ²) = 0 时，lim_(n → ∞)xₙ = 0(D) 当 lim_(n → ∞)(xₙ+sin xₙ) = 0 时，lim_(n → ∞)xₙ = 0","a":"D。"},{"y":2018,"o":9,"s":"lim_(x → +∞)x²l[arctan(x+1)-arctan xr] = ________。","a":"1。"},{"y":2019,"o":9,"s":"lim_(x → 0)(x+2ˣ)^(frac2x) = ________。","a":"4e²。"},{"y":2021,"o":17,"s":"求极限 lim_(x → 0)((1+∫₀ˣe^(t²)dt)/(eˣ-1)-1/(sin x))。","a":"dfrac12（与数学一 2021 第 17 题同题）。"},{"y":2022,"o":11,"s":"lim_(x → 0)((1+eˣ)/2)^(cot x) = ________。","a":"sqrte（与数学三 2022 第 11 题同题）。"},{"y":2026,"o":12,"s":"设 lim_(x → 0)(dfrac1x-(ln(1+x))/(xsin x)) = ________。","a":"dfrac12（与数学一 2026 第 12 题同题）。"}],"Kcdaedae1|2":[{"y":2013,"o":1,"s":"设 cos x-1 = xsinα(x)，其中 |α(x)| < π/2，则当 x → 0 时，α(x) 是（ ）(A) 比 x 高阶的无穷小量 (B) 比 x 低阶的无穷小量(C) 与 x 同阶但不等价的无穷小量 (D) 与 x 等价的无穷小量","a":"C。"},{"y":2016,"o":1,"s":"设 α₁ = x(cos√(x)-1)，α₂ = √(x)ln(1+sqrt[3]x)，α₃ = sqrt[3]x+1-1。当 x → 0⁺ 时，以上 3 个无穷小量按照从低阶到高阶的排序是（ ）(A) α₁,α₂,α₃ (B) α₂,α₃,α₁ (C) α₂,α₁,α₃ (D) α₃,α₂,α₁","a":"B。"},{"y":2020,"o":1,"s":"x → 0⁺ 时，下列无穷小量中最高阶是（ ）(A) ∫₀ˣ(e^(t²)-1)dt (B) ∫₀ˣln(1+√(t³))dt(C) ∫₀^(sin x)sin t² dt (D) ∫₀^(1-cos x)√(sin³t) dt","a":"D。"},{"y":2021,"o":1,"s":"当 x → 0 时，∫₀^(x²)(e^(t³)-1)dt 是 x⁷ 的（ ）(A) 低阶无穷小 (B) 等价无穷小 (C) 高阶无穷小 (D) 同阶但非等价无穷小","a":"C。"},{"y":2022,"o":1,"s":"当 x → 0 时，α(x),β(x) 是非零无穷小量，则以下的命题中：① 若 α(x)∼β(x)，则 α²(x)∼β²(x)；② 若 α²(x)∼β²(x)，则 α(x)∼β(x)；③ 若 α(x)∼β(x)，则 α(x)-β(x) = o(α(x))；④ 若 α(x)-β(x) = o(α(x))，则 α(x)∼β(x)。真命题的序号为（ ）(A) ①③ (B) ①④ (C) ①③④ (D) ②③④","a":"C。"},{"y":2023,"o":3,"s":"已知数列 {xₙ},{yₙ} 满足 x₁ = y₁ = dfrac12，xₙ₊₁ = sin xₙ，yₙ₊₁ = yₙ² (n = 1,2,⋯)，则当 n → ∞ 时，（ ）(A) xₙ 是 yₙ 的高阶无穷小 (B) yₙ 是 xₙ 的高阶无穷小(C) xₙ 是 yₙ 的等价无穷小 (D) xₙ 是 yₙ 的同阶但非等价无穷小","a":"B。"},{"y":2025,"o":4,"s":"设函数 f(x),g(x) 在 x = 0 的某去心邻域内有定义且恒不为零，若当 x → 0 时，f(x) 是 g(x) 的高阶无穷小，则当 x → 0 时（ ）(A) f(x)+g(x) = o(g(x)) (B) f(x)g(x) = o(f²(x))(C) f(x) = o(eᵍ⁽ˣ⁾-1) (D) f(x) = o(g²(x))","a":"C。"},{"y":2026,"o":1,"s":"已知当 x → 0 时，ax²+bx+arcsin x 与 sqrt[3]1+x²-1 是等价无穷小，则（ ）(A) a = dfrac13, b = -1 (B) a = dfrac13, b = 1 (C) a = dfrac23, b = -1 (D) a = dfrac23, b = 1","a":"A。"}],"Ke9053521|2":[{"y":2009,"o":2,"s":"当 x → 0 时，f(x) = x-sin ax 与 g(x) = x²ln(1-bx) 是等价无穷小，则（ ）(A) a = 1, b = -dfrac16 (B) a = 1, b = dfrac16 (C) a = -1, b = -dfrac16 (D) a = -1, b = dfrac16","a":"A。"},{"y":2011,"o":1,"s":"已知当 x → 0 时，函数 f(x) = 3sin x-sin 3x 与 cxᵏ 是等价无穷小，则（ ）(A) k = 1, c = 4 (B) k = 1, c = -4 (C) k = 3, c = 4 (D) k = 3, c = -4","a":"C。"},{"y":2012,"o":15,"s":"已知函数 f(x) = (1+x)/(sin x)-dfrac1x，记 a = lim_(x → 0)f(x)。I. 求 a 的值；II. 若当 x → 0 时，f(x)-a 与 xᵏ 是同阶无穷小，求常数 k 的值。","a":"a = 1，k = 1。"},{"y":2013,"o":15,"s":"当 x → 0 时，1-cos x·cos 2x·cos 3x 与 axⁿ 为等价无穷小，求 n 与 a 的值。","a":"n = 2，a = 7。"},{"y":2014,"o":1,"s":"当 x → 0⁺ 时，若 ln^α(1+2x)，(1-cos x)^(frac1α) 均是比 x 高阶的无穷小量，则 α 的取值范围是（ ）(A) (2,+∞) (B) (1,2) (C) (dfrac12,1) (D) (0,dfrac12)","a":"B。"},{"y":2015,"o":15,"s":"设函数 f(x) = x+aln(1+x)+bxsin x，g(x) = kx³。若 f(x) 与 g(x) 在 x → 0 时是等价无穷小，求 a,b,k 的值。","a":"a = -1，b = -dfrac12，k = -dfrac13。"},{"y":2018,"o":1,"s":"若 lim_(x → 0)(eˣ+ax²+bx)^(frac1x²) = 1，则（ ）(A) a = dfrac12, b = -1 (B) a = -dfrac12, b = -1 (C) a = dfrac12, b = 1 (D) a = -dfrac12, b = 1","a":"B。"},{"y":2019,"o":1,"s":"当 x → 0 时，若 x-tan x 与 xᵏ 是同阶无穷小，则 k = （ ）(A) 1 (B) 2 (C) 3 (D) 4","a":"C。"},{"y":2023,"o":11,"s":"当 x → 0 时，函数 f(x) = ax+bx²+ln(1+x) 与 g(x) = e^(x²)-cos x 是等价无穷小，则 ab = ________。","a":"ab = -2。"}],"K71a29108|2":[{"y":2009,"o":1,"s":"函数 f(x) = (x-x³)/(sinπ x) 的可去间断点的个数为（ ）(A) 1 (B) 2 (C) 3 (D) 无穷多个","a":"C，共 3 个可去间断点，x = 0, ±1。"},{"y":2010,"o":1,"s":"函数 f(x) = (x²-x)/(x²-1)√(1+dfrac1x²) 的无穷间断点的个数为（ ）(A) 0 (B) 1 (C) 2 (D) 3","a":"B，只有 x = -1 一个无穷间断点。"},{"y":2015,"o":2,"s":"函数 f(x) = lim_(t → 0)(1+(sin t)/x)^(x²/t) 在 (-∞,+∞) 内（ ）(A) 连续 (B) 有可去间断点 (C) 有跳跃间断点 (D) 有无穷间断点","a":"B，x = 0 为可去间断点。"},{"y":2017,"o":1,"s":"设函数f(x) = (1-cos√(x))/ax (x > 0), f(x) = b (x ≤0)在 x = 0 处连续，则（ ）(A) ab = dfrac12 (B) ab = -dfrac12 (C) ab = 0 (D) ab = 2","a":"A，ab = dfrac12。"},{"y":2018,"o":3,"s":"设函数f(x) = -1 (x < 0), f(x) = 1 (x ≥0),g(x) = 2-ax (x ≤ -1), g(x) = x (-1 < x < 0), g(x) = x-b (x ≥0).若 f(x)+g(x) 在 R 上连续，则（ ）(A) a = 3,b = 1 (B) a = 3,b = 2 (C) a = -3,b = 1 (D) a = -3,b = 2","a":"D，a = -3, b = 2。"},{"y":2020,"o":2,"s":"函数 f(x) = (e^(frac1x-1)ln|1+x|)/((eˣ-1)(x-2)) 的第二类间断点的个数为（ ）(A) 1 (B) 2 (C) 3 (D) 4","a":"C，共 3 个第二类间断点，x = -1, 1, 2。"},{"y":2024,"o":1,"s":"函数 f(x) = |x|^(frac1(1-x)(x-2)) 的第一类间断点的个数是（ ）(A) 3 (B) 2 (C) 1 (D) 0","a":"C，只有 x = 1 一个第一类间断点。"}],"K547f1fa4|2":[{"y":2011,"o":2,"s":"设函数 f(x) 在 x = 0 处可导，且 f(0) = 0，则 lim_(x → 0)(x²f(x)-2f(x³))/x³ = （ ）(A) -2f'(0)(B) -f'(0)(C) f'(0)(D) 0","a":"B。"},{"y":2013,"o":2,"s":"设函数 y = f(x) 由方程 cos(xy)+ln y-x = 1 确定，则 lim_(n → ∞)n[f(2/n)-1] = （ ）(A) 2(B) 1(C) -1(D) -2","a":"A。"},{"y":2015,"o":3,"s":"设函数 f(x) 当 x > 0 时 f(x) = x^αcos1/x^β，当 x ≤0 时 f(x) = 0，其中 α > 0,β > 0。若 f'(x) 在 x = 0 处连续，则（ ）(A) α-β > 1(B) 0 < α-β ≤1(C) α-β > 2(D) 0 < α-β ≤2","a":"A。"},{"y":2018,"o":2,"s":"下列函数中，在 x = 0 处不可导的是（ ）(A) f(x) = |x|sin|x|(B) f(x) = |x|sin√(|x|)(C) f(x) = cos|x|(D) f(x) = cos√(|x|)","a":"D。"},{"y":2021,"o":2,"s":"设 f(x) = (eˣ-1)/x（x ≠0），且 f(0) = 1，则 f(x) 在 x = 0 处（ ）(A) 连续且取得极大值(B) 连续且取得极小值(C) 可导且导数为零(D) 可导且导数不为零","a":"D。"},{"y":2022,"o":17,"s":"已知函数 f(x) 在 x = 1 处可导，且 lim_(x → 0)(f(e^(x²))-3f(1+sin²x))/x² = 2，求 f'(1)。","a":"f'(1) = -1。"},{"y":2023,"o":5,"s":"设函数 y = f(x) 由参数方程 x = 2t+|t|、y = |t|sin t 确定，则（ ）(A) f(x) 连续，f'(0) 不存在(B) f'(0) 存在，f'(x) 在 x = 0 处不连续(C) f'(x) 连续，f''(0) 不存在(D) f''(0) 存在，f''(x) 在 x = 0 处不连续","a":"C。"},{"y":2024,"o":2,"s":"设函数 y = f(x) 由参数方程 x = 1+t³、y = e^(t²) 确定，则 lim_(x → +∞)x[f(2+2/x)-f(2)] = （ ）(A) 2e(B) 4e/3(C) 2e/3(D) e/3","a":"B。"},{"y":2025,"o":7,"s":"设函数 f(x) 连续，给出下列四个条件：① lim_(x → 0)(|f(x)|-f(0))/x 存在；② lim_(x → 0)(f(x)-|f(0)|)/x 存在；③ lim_(x → 0)(|f(x)|)/x 存在；④ lim_(x → 0)(|f(x)|-|f(0)|)/x 存在。其中能得到「f(x) 在 x = 0 处可导」的条件个数是（ ）(A) 1(B) 2(C) 3(D) 4","a":"D。"},{"y":2025,"o":18,"s":"设函数 f(x) 在 x = 0 处连续，且 lim_(x → 0)(xf(x)-e^(2sin x)+1)/(ln(1+x)+ln(1-x)) = -3，证明 f(x) 在 x = 0 处可导，并求 f'(0)。","a":"f'(0) = 5。"}],"Kde439863|2":[{"y":2009,"o":12,"s":"设 y = y(x) 是由方程 xy+eʸ = x+1 确定的隐函数，则 .d²y/dx²|ₓ₌₀ = ＿＿＿","a":"-3"},{"y":2010,"o":11,"s":"函数 y = ln(1-2x) 在 x = 0 处的 n 阶导数 y⁽ⁿ⁾(0) = ＿＿＿","a":"-2ⁿ(n-1)!"},{"y":2012,"o":2,"s":"设函数 f(x) = (eˣ-1)(e²ˣ-2)⋯(eⁿˣ-n)，其中 n 为正整数，则 f'(0) = （ ）(A) (-1)ⁿ⁻¹(n-1)!(B) (-1)ⁿ(n-1)!(C) (-1)ⁿ⁻¹n!(D) (-1)ⁿn!","a":"A"},{"y":2012,"o":9,"s":"设 y = y(x) 是由方程 x²-y+1 = eʸ 所确定的隐函数，则 .d²y/dx²|ₓ₌₀ = ＿＿＿","a":"1"},{"y":2013,"o":10,"s":"设函数 f(x) = ∫₋₁ˣ√(1-eᵗ) dt，则 y = f(x) 的反函数 x = f⁻¹(y) 在 y = 0 处的导数 .dx/dy|_(y = 0) = ＿＿＿","a":"√(e/(e-1))"},{"y":2015,"o":9,"s":"设 x = arctan t，y = 3t+t³，则 .d²y/dx²|ₜ₌₁ = ＿＿＿","a":"48"},{"y":2015,"o":10,"s":"函数 f(x) = x²2ˣ 在 x = 0 处的 n 阶导数 f⁽ⁿ⁾(0) = ＿＿＿","a":"n(n-1)(ln 2)ⁿ⁻²"},{"y":2016,"o":12,"s":"已知函数 f(x) 在 (-∞,+∞) 上连续，且 f(x) = (x+1)²+2∫₀ˣf(t) dt，则当 n ≥2 时，f⁽ⁿ⁾(0) = ＿＿＿","a":"5· 2ⁿ⁻¹"},{"y":2017,"o":10,"s":"设函数 y = y(x) 由参数方程 x = t+eᵗ、y = sin t 确定，则 .d²y/dx²|ₜ₌₀ = ＿＿＿","a":"-1/8"},{"y":2020,"o":4,"s":"已知函数 f(x) = x²ln(1-x)，当 n ≥3 时，f⁽ⁿ⁾(0) = （ ）(A) -n!/(n-2)(B) n!/(n-2)(C) -((n-2)!)/n(D) ((n-2)!)/n","a":"A"},{"y":2020,"o":9,"s":"设 x = √(t²+1)，y = ln(t+√(t²+1))，则 .d²y/dx²|ₜ₌₁ = ＿＿＿","a":"-√(2)"},{"y":2021,"o":12,"s":"设函数 y = y(x) 由参数方程 x = 2eᵗ+t+1、y = 4(t-1)eᵗ+t² 确定，则 .d²y/dx²|ₜ₌₀ = ＿＿＿","a":"2/3"},{"y":2022,"o":12,"s":"已知函数 y = y(x) 由方程 x²+xy+y³ = 3 确定，则 y''(1) = ＿＿＿","a":"-31/32"},{"y":2024,"o":14,"s":"已知函数 f(x) = x²(eˣ+1)，则 f⁽⁵⁾(1) = ＿＿＿","a":"31e"},{"y":2025,"o":14,"s":"已知函数 y = y(x) 由 x = ln(1+2t) 与 2t-∫₁^(y+t²)e^(-u²) du = 0 确定，则 .dy/dx|ₜ₌₀ = ＿＿＿","a":"e"},{"y":2026,"o":6,"s":"已知函数 f(x) = ∫₁^(x³)eᵗ/(1+t²) dt，f 的反函数为 g，则（ ）(A) g(0) = 1, g'(0) = 3/2e(B) g(0) = 1, g'(0) = 2/3e(C) g(1) = 0, g'(1) = 3/2e(D) g(1) = 0, g'(1) = 2/3e","a":"B"}],"K9578b3de|2":[{"y":2009,"o":5,"s":"若 f''(x) 不变号，且曲线 y = f(x) 在点 (1,1) 处的曲率圆为 x²+y² = 2，则函数 f(x) 在区间 (1,2) 内（ ）(A) 有极值点，无零点(B) 无极值点，有零点(C) 有极值点，有零点(D) 无极值点，无零点","a":"B。"},{"y":2009,"o":9,"s":"曲线由参数方程x = ∫₀¹⁻ᵗe^(-u²) du, y = t²ln(2-t²)确定，则它在点 (0,0) 处的切线方程为 ______","a":"y = 2x。"},{"y":2010,"o":3,"s":"曲线 y = x² 与曲线 y = aln x (a ≠0) 相切，则 a = （ ）(A) 4e(B) 3e(C) 2e(D) e","a":"C，即 a = 2e。"},{"y":2010,"o":13,"s":"已知一个长方形的长 l 以 2 cm/s 的速率增加，宽 w 以 3 cm/s 的速率增加，则当 l = 12 cm、w = 5 cm 时，它的对角线增加的速率为 ______","a":"3 cm/s。"},{"y":2012,"o":13,"s":"曲线 y = x²+x (x < 0) 上曲率为 (sqrt2)/2 的点的坐标是 ______","a":"(-1,0)。"},{"y":2013,"o":12,"s":"曲线由参数方程x = arctan t, y = ln√(1+t²)确定，求它对应于 t = 1 的点处的法线方程。","a":"x+y = π/4+frac12ln 2。"},{"y":2014,"o":4,"s":"曲线由参数方程x = t²+7, y = t²+4t+1确定，求它对应于 t = 1 的点处的曲率半径。(A) (√(10))/50(B) (√(10))/100(C) 10√(10)(D) 5√(10)","a":"C，即 10√(10)。"},{"y":2014,"o":12,"s":"曲线 L 的极坐标方程是 r = θ，则 L 在点 (r,θ) = l(π/2,π/2r) 处的切线的直角坐标方程是 ______","a":"2/πx+y-π/2 = 0。"},{"y":2016,"o":13,"s":"已知动点 P 在曲线 y = x³ 上运动，记坐标原点与点 P 间的距离为 l。若点 P 的横坐标对时间的变化率为常数 v₀，则当点 P 运动到点 (1,1) 时，l 对时间的变化率是 ______","a":"2sqrt2 v₀。"},{"y":2018,"o":12,"s":"曲线由参数方程x = cos³ t, y = sin³ t确定，求它在 t = π/4 对应点处的曲率。","a":"frac23。"},{"y":2019,"o":6,"s":"已知 f(x)、g(x) 二阶可导，且 2 阶导函数在 x = a 处连续，则 lim_(x → a)(f(x)-g(x))/((x-a)²) = 0 是曲线 y = f(x) 和 y = g(x) 在 x = a 对应的点处相切且曲率相等的（ ）(A) 充分非必要条件(B) 充分必要条件(C) 必要非充分条件(D) 既非充分又非必要条件","a":"A。"},{"y":2019,"o":10,"s":"曲线由参数方程x = t-sin t, y = 1-cos t确定，求它在 t = 3π/2 对应点处的切线在 y 轴上的截距。","a":"3π/2+2。"},{"y":2021,"o":3,"s":"有一圆柱体，底面半径与高随时间的变化率分别为 2 cm/s、-3 cm/s，当底面半径为 10 cm、高为 5 cm 时，圆柱体的体积与表面积随时间的变化速率为（ ）(A) 125π cm³/s，40π cm²/s(B) 125π cm³/s，-40π cm²/s(C) -100π cm³/s，40π cm²/s(D) -100π cm³/s，-40π cm²/s","a":"C。"},{"y":2023,"o":14,"s":"曲线 3x³ = y⁵+2y³ 在 x = 1 对应点处的法线斜率为 ______","a":"-11/9。"},{"y":2024,"o":11,"s":"曲线 y² = x 在点 (0,0) 处的曲率圆方程为 ______","a":"l(x-frac12r)²+y² = frac14。"},{"y":2024,"o":15,"s":"设某物体以速度 v(t) = t+ksinπ t 做直线运动。若它从 t = 0 到 t = 3 的时间段内平均速度是 frac52，则 k = ______","a":"3π/2。"},{"y":2026,"o":13,"s":"设曲线 x²+2sqrt3 xy+y² = 1 在点 (0,1) 处的曲率半径为 ______","a":"4。"}],"Kdd1ee30c|2":[{"y":2009,"o":13,"s":"函数 y = x²ˣ 在区间 (0,1] 上的最小值为 underline。","a":"e^(-2/e)。"},{"y":2010,"o":15,"s":"求函数 f(x) = ∫₁^(x²)(x²-t) e^(-t²) dt 的单调区间与极值。","a":"单调增加区间为 (-1,0) 与 (1,+∞)，单调减少区间为 (-∞,-1) 与 (0,1)；极大值 f(0) = dfrac12l(1-dfrac1er)，极小值 f(±1) = 0。"},{"y":2017,"o":18,"s":"已知函数 y = y(x) 由方程 x³+y³-3x+3y-2 = 0 确定，求 y(x) 的极值。","a":"极大值 y(1) = 1，极小值 y(-1) = 0。"},{"y":2019,"o":15,"s":"已知函数当 x > 0 时，f(x) = x²ˣ；当 x ≤0 时，f(x) = x eˣ+1。求 f'(x)，并求 f(x) 的极值。","a":"当 x < 0 时 f'(x) = eˣ(x+1)，当 x > 0 时 f'(x) = 2x²ˣ(ln x+1)；f(x) 在 x = 0 处不可导。极大值 f(0) = 1，极小值 f(-1) = 1-e⁻¹、f(1/"},{"y":2020,"o":6,"s":"设函数 f(x) 在区间 [-2,2] 上可导，且 f'(x) > f(x) > 0，则（ ）(A) (f(-2))/(f(-1)) > 1(B) (f(0))/(f(-1)) > e(C) (f(1))/(f(-1)) < e²(D) (f(2))/(f(-1)) < e³","a":"B。"},{"y":2026,"o":5,"s":"设函数 f(x) 在区间 [-1,1] 上有定义，则（ ）(A) 当 f(x) 在 (-1,0) 单调递减，在 (0,1) 单调递增时，f(0) 是极小值(B) 当 f(0) 是极小值时，f(x) 在 (-1,0) 单调递减，在 (0,1) 单调递增(C) 当 f(x) 的图形在 [-1,1] 是凹的时，(f(x)-f(1))/(x-1) 在 [-1,1) 单调递增(D) 当 (f(x)-f(1))/(x-1) 在 [-1,1) 单调递增时，f(x) 的图形在 [-1,1] 是凹的","a":"C。"}],"Kac3d5ac3|2":[{"y":2010,"o":10,"s":"曲线 y = 2x³/(x²+1) 的渐近线方程为 ________","a":"y = 2x。"},{"y":2011,"o":16,"s":"设函数 y = y(x) 由参数方程x = frac13 t³+t+frac13, y = frac13 t³-t+frac13所确定，求 y = y(x) 的极值和曲线 y = y(x) 的凹凸区间及拐点。","a":"极大值为 y(-1) = 1，极小值为 y(5/3) = -1/3；凹区间为 (1/3,+∞)，凸区间为 (-∞,1/3)，拐点为 (1/3,1/3)。"},{"y":2012,"o":1,"s":"曲线 y = (x²+x)/(x²-1) 的渐近线的条数为（ ）(A) 0(B) 1(C) 2(D) 3","a":"C（共 2 条）。"},{"y":2014,"o":2,"s":"下列曲线中有渐近线的是（ ）(A) y = x+sin x(B) y = x²+sin x(C) y = x+sindfrac1x(D) y = x²+sindfrac1x","a":"C。"},{"y":2014,"o":3,"s":"设函数 f(x) 具有 2 阶导数，g(x) = f(0)(1-x)+f(1)x，则在区间 [0,1] 上，（ ）(A) 当 f'(x) ≥0 时，f(x) ≥ g(x)(B) 当 f'(x) ≥0 时，f(x) ≤ g(x)(C) 当 f''(x) ≥0 时，f(x) ≥ g(x)(D) 当 f''(x) ≥0 时，f(x) ≤ g(x)","a":"D。"},{"y":2015,"o":4,"s":"设函数 f(x) 在 (-∞,+∞) 内连续，其 2 阶导函数 f''(x) 的图形如图所示，则曲线 y = f(x) 的拐点个数为（ ）(A) 0(B) 1(C) 2(D) 3图形描述：f''(x) 的图象在平面直角坐标系中。横轴除原点外无具体刻度，纵轴无刻度。左侧一支为开口向上的曲线，其最低点恰与 x 轴相切（即有一处 f'' = 0 但两侧均为正、不变号）；在 x = 0 处曲线断开，f'' 无定义；右侧一支从 x 轴下方上升，穿过 x 轴一次后再位于上方。","a":"C（2 个）。"},{"y":2016,"o":4,"s":"设函数 f(x) 在 (-∞,+∞) 内连续，其导函数的图形如图所示，则（ ）(A) 函数 f(x) 有 2 个极值点，曲线 y = f(x) 有 2 个拐点(B) 函数 f(x) 有 2 个极值点，曲线 y = f(x) 有 3 个拐点(C) 函数 f(x) 有 3 个极值点，曲线 y = f(x) 有 1 个拐点(D) 函数 f(x) 有 3 个极值点，曲线 y = f(x) 有 2 个拐点图形描述：y = f'(x) 的图象。曲线与 x 轴有两个变号交点（记为 x₁、x₃），另有一处与 x 轴相切（记为 x₄，f' = 0 但不变号）；在 x₂ 处（竖直虚线）曲线断开，f' 无定义。f' 在右侧区间有一个局部极大值点和一个局部极小值点（即相切处）。","a":"B。"},{"y":2016,"o":5,"s":"设函数 f_i(x) (i = 1,2) 具有二阶连续导数，且 f_i''(x₀) < 0 (i = 1,2)。若两条曲线 y = f_i(x) (i = 1,2) 在点 (x₀,y₀) 处具有公切线 y = g(x)，且在该点处曲线 y = f₁(x) 的曲率大于曲线 y = f₂(x) 的曲率，则在 x₀ 的某个邻域内，有（ ）(A) f₁(x) ≤ f₂(x) ≤ g(x)(B) f₂(x) ≤ f₁(x) ≤ g(x)(C) f₁(x) ≤ g(x) ≤ f₂(x)(D) f₂(x) ≤ g(x) ≤ f₁(x)","a":"A。"},{"y":2016,"o":9,"s":"曲线 y = x³/(1+x²)+arctan(1+x²) 的斜渐近线方程为 ________","a":"y = x+π/2。"},{"y":2017,"o":2,"s":"设二阶可导函数 f(x) 满足 f(1) = f(-1) = 1，f(0) = -1 且 f''(x) > 0，则（ ）(A) ∫₋₁¹f(x) dx > 0(B) ∫₋₁¹f(x) dx < 0(C) ∫₋₁⁰f(x) dx > ∫₀¹f(x) dx(D) ∫₋₁⁰f(x) dx < ∫₀¹f(x) dx","a":"B。"},{"y":2017,"o":9,"s":"曲线 y = x(1+arcsin2/x) 的斜渐近线方程为 ________","a":"y = x+2。"},{"y":2018,"o":4,"s":"设函数 f(x) 在 [0,1] 上二阶可导，且 ∫₀¹f(x) dx = 0，则（ ）(A) 当 f'(x) < 0 时，f(dfrac12) < 0(B) 当 f''(x) < 0 时，f(dfrac12) < 0(C) 当 f'(x) > 0 时，f(dfrac12) < 0(D) 当 f''(x) > 0 时，f(dfrac12) < 0","a":"D。"},{"y":2018,"o":10,"s":"曲线 y = x²+2ln x 在其拐点处的切线方程是 ________","a":"y = 4x-3。"},{"y":2019,"o":2,"s":"曲线 y = xsin x+2cos x (-π/2 < x < 2π) 的拐点坐标为（ ）(A) (0,2)(B) (π,-2)(C) (π/2,π/2)(D) (3π/2,-3π/2)","a":"B（(π,-2)）。"},{"y":2020,"o":15,"s":"求曲线 y = (x¹⁺ˣ)/((1+x)ˣ) (x > 0) 的斜渐近线方程。","a":"y = x/e+1/2e。"},{"y":2021,"o":18,"s":"已知 f(x) = (x|x|)/(1+x)，求函数 y = f(x) 的凹凸区间及渐近线。","a":"凹区间为 (-∞,-1) 与 (0,+∞)，凸区间为 (-1,0)；渐近线为 x = -1、y = -x+1、y = x-1（共 3 条）。"},{"y":2022,"o":3,"s":"设函数 f(x) 在 x = x₀ 处有二阶导数，则（ ）(A) 当 f(x) 在 x₀ 的某邻域内单调增加时，f'(x₀) > 0(B) 当 f'(x₀) > 0 时，f(x) 在 x₀ 的某邻域内单调增加(C) 当 f(x) 在 x₀ 的某邻域内是凹函数时，f''(x₀) > 0(D) 当 f''(x₀) > 0 时，f(x) 在 x₀ 的某邻域内是凹函数","a":"B。"},{"y":2023,"o":1,"s":"曲线 y = xln(e+1/(x-1)) 的斜渐近线方程为（ ）(A) y = x+e(B) y = x+dfrac1e(C) y = x(D) y = x-dfrac1e","a":"B。"},{"y":2023,"o":7,"s":"设函数 f(x) = (x²+a)eˣ，若 f(x) 没有极值点，但曲线 y = f(x) 有拐点，则 a 的取值范围是（ ）(A) [0,1)(B) [1,+∞)(C) [1,2)(D) [2,+∞)","a":"C。"},{"y":2025,"o":2,"s":"已知函数 f(x) = ∫₀ˣ e^(t²)sin t dt，g(x) = ∫₀ˣ e^(t²)dt·sin² x，则（ ）(A) x = 0 是 f(x) 的极值点，也是 g(x) 的极值点(B) x = 0 是 f(x) 的极值点，(0,0) 是曲线 y = g(x) 的拐点(C) x = 0 是 f(x) 的极值点，(0,0) 是曲线 y = f(x) 的拐点(D) (0,0) 是曲线 y = f(x) 的拐点，也是曲线 y = g(x) 的拐点","a":"B。"},{"y":2025,"o":12,"s":"曲线 y = sqrt[3]x³-3x²+1 的渐近线方程为 ________","a":"y = x-1。"}],"K0318406f|2":[{"y":2011,"o":3,"s":"函数 f(x) = ln|(x-1)(x-2)(x-3)| 的驻点个数为（ ）(A) 0(B) 1(C) 2(D) 3","a":"C。"},{"y":2012,"o":21,"s":"I. 证明方程 xⁿ+xⁿ⁻¹+⋯+x = 1（n 为大于 1 的整数）在区间 (dfrac12,1) 内有且仅有一个实根；II. 记第 I 问中的实根为 xₙ，证明 lim_(n → ∞)xₙ 存在，并求此极限。","a":"第 I 问方程在 (dfrac12,1) 内有且仅有一个实根；第 II 问极限存在且为 dfrac12。"},{"y":2015,"o":19,"s":"已知函数 f(x) = ∫ₓ¹√(1+t²) dt+∫₁^(x²)√(1+t) dt，求 f(x) 零点的个数。","a":"f(x) 在 (-∞,+∞) 上共有 2 个零点。"},{"y":2017,"o":19,"s":"设函数 f(x) 在区间 [0,1] 上具有二阶导数，且 f(1) > 0，lim_(x → 0⁺)(f(x))/x < 0。证明：I. 方程 f(x) = 0 在区间 (0,1) 内至少存在一个实根；II. 方程 f(x)f''(x)+l[f'(x)r]² = 0 在区间 (0,1) 内至少存在两个不同实根。","a":"证明题，结论即思路 4 的罗尔定理链。"},{"y":2021,"o":4,"s":"设函数 f(x) = ax-bln x（a > 0）有 2 个零点，则 dfracba 的取值范围是（ ）(A) (e,+∞)(B) (0,e)(C) (0,dfrac1e)(D) (dfrac1e,+∞)","a":"A。"}],"K68217a44|2":[{"y":2012,"o":20,"s":"证明：xln(1+x)/(1-x)+cos x ≥1+x²/2（-1 < x < 1）。","a":"证明题，不等式对一切 -1 < x < 1 成立。"},{"y":2018,"o":18,"s":"已知常数 k ≥ ln 2-1。证明：(x-1)(x-ln²x+2kln x-1) ≥0。","a":"证明题，不等式对一切 x > 0 成立。"}],"K4586eb88|2":[{"y":2009,"o":21,"s":"Ⅰ. 证明拉格朗日中值定理：若函数 f(x) 在 [a,b] 上连续，在 (a,b) 内可导，则存在点 ξ∈(a,b)，使得 f(b)-f(a) = f'(ξ)(b-a)。Ⅱ. 证明：若函数 f(x) 在 x = 0 处连续，在 (0,δ)（δ > 0）内可导，且 lim_(x → 0⁺)f'(x) = A，则 f'₊(0) 存在，且 f'₊(0) = A。","a":"证明题（两问），结论分别为拉格朗日中值定理与右导数的极限公式。"},{"y":2010,"o":21,"s":"假设函数 f(x) 在闭区间 [0,1] 上连续，在开区间 (0,1) 内可导，且 f(0) = 0，f(1) = dfrac13。证明：存在 ξ∈(0,dfrac12)，η∈(dfrac12,1)，使得 f'(ξ)+f'(η) = ξ²+η²。","a":"证明题，辅助函数 g(x) = f(x)-x³/3 在两段区间各用一次拉格朗日中值定理。"},{"y":2013,"o":18,"s":"设奇函数 f(x) 在 [-1,1] 上具有 2 阶导数，且 f(1) = 1。证明：Ⅰ. 存在 ξ∈(0,1)，使得 f'(ξ) = 1；Ⅱ. 存在 η∈(-1,1)，使得 f''(η)+f'(η) = 1。","a":"证明题（两问），第Ⅰ问用拉格朗日中值定理，第Ⅱ问构造 g(x) = f'(x)+f(x)-x 或 G(x) = eˣ[f'(x)-1] 用罗尔定理。"},{"y":2015,"o":21,"s":"已知函数 f(x) 在区间 [a,+∞) 上具有 2 阶导数，f(a) = 0，f'(x) > 0，f''(x) > 0。设 b > a，曲线 y = f(x) 在点 (b,f(b)) 处的切线与 x 轴的交点是 (x₀,0)，证明 a < x₀ < b。","a":"证明题，x₀ = b-(f(b))/(f'(b))，由 f(b) > 0 得 x₀ < b，再由弦斜率小于切线斜率得 x₀ > a。"},{"y":2019,"o":21,"s":"已知函数 f(x) 在 [0,1] 上具有 2 阶导数，且 f(0) = 0，f(1) = 1，∫₀¹ f(x) dx = 1。证明：Ⅰ. 存在 ξ∈(0,1)，使得 f'(ξ) = 0；Ⅱ. 存在 η∈(0,1)，使得 f''(η) < -2。","a":"证明题（两问），第Ⅰ问三条路径（变限积分搭桥、反证法、最值加费马引理），第Ⅱ问对 f(x)+x² 用两次拉格朗日或构造抛物线比较。"},{"y":2020,"o":20,"s":"设函数 f(x) = ∫₁ˣ e^(t²) dt。Ⅰ. 证明：存在 ξ∈(1,2)，使得 f(ξ) = (2-ξ)e^(ξ²)；Ⅱ. 证明：存在 η∈(1,2)，使得 f(2) = ln 2·η e^(η²)。","a":"证明题（两问），第Ⅰ问可用零点定理、罗尔定理（令 (x-2)f(x)）或交换积分次序，第Ⅱ问对 f 与 ln x 用柯西中值定理。"},{"y":2022,"o":21,"s":"设函数 f(x) 在 (-∞,+∞) 上有二阶连续导数，证明：f''(x) ≥0 的充分必要条件是对任意不同的实数 a,b，都有f((a+b)/2) ≤1/(b-a)∫ₐᵇ f(x) dx成立。","a":"证明题，必要性用中点处泰勒展开（法一）或构造变限积分辅助函数（法二），充分性用反证法或洛必达法则。"},{"y":2023,"o":21,"s":"设函数 f(x) 在 [-a,a] 上具有二阶连续导数，证明：Ⅰ. 若 f(0) = 0，则存在 ξ∈(-a,a)，使得f''(ξ) = 1/a²l[f(a)+f(-a)r];Ⅱ. 若 f(x) 在 (-a,a) 内取得极值，则存在 η∈(-a,a)，使得l|f''(η)r| ≥1/2a²l|f(a)-f(-a)r|.","a":"证明题（两问），均在 f(0) 或极值点处泰勒展开，配合最值放缩与介值定理。"},{"y":2024,"o":21,"s":"设函数 f(x) 具有二阶导数，且 f'(0) = f'(1)，l|f''(x)r| ≤1。证明：Ⅰ. 当 x∈(0,1) 时，l|f(x)-f(0)(1-x)-f(1)xr| ≤ (x(1-x))/2;Ⅱ.|∫₀¹ f(x) dx-(f(0)+f(1))/2| ≤1/12.","a":"证明题（两问），第Ⅰ问在 x = 0 与 x = 1 两点泰勒展开消去 f' 项（或构造二次函数用凹凸性），第Ⅱ问将第Ⅰ问的不等式积分。"},{"y":2025,"o":21,"s":"设函数 f(x) 在区间 (a,b) 内可导，证明导函数 f'(x) 在 (a,b) 内严格单调增加的充分必要条件是：对 (a,b) 内任意的 x₁,x₂,x₃，当 x₁ < x₂ < x₃ 时，有(f(x₂)-f(x₁))/(x₂-x₁) < (f(x₃)-f(x₂))/(x₃-x₂).","a":"证明题，必要性直接用两次拉格朗日中值定理，充分性对弦斜率取单侧极限。"}],"K167393e9|2":[{"y":2021,"o":5,"s":"设函数 f(x) = sec x 在 x = 0 处的 2 次泰勒多项式为 1+ax+bx²，则（ ）(A) a = 1, b = -dfrac12(B) a = 1, b = dfrac12(C) a = 0, b = -dfrac12(D) a = 0, b = dfrac12","a":"D。"}],"K59e1e05f|2":[{"y":2009,"o":16,"s":"计算不定积分 ∫ ln(1+√((1+x)/x))dx（x > 0）。","a":"xln(1+√((1+x)/x))+dfrac12ln(√(1+x)+√(x))-(√(x))/(2(√(1+x)+√(x)))+C（C 为任意常数）。"},{"y":2016,"o":2,"s":"已知函数 f(x)：当 x < 1 时 f(x) = 2(x-1)；当 x ≥1 时 f(x) = ln x。则 f(x) 的一个原函数是（ ）(A) F(x)：当 x < 1 时 F(x) = (x-1)²；当 x ≥1 时 F(x) = x(ln x-1)(B) F(x)：当 x < 1 时 F(x) = (x-1)²；当 x ≥1 时 F(x) = x(ln x+1)-1(C) F(x)：当 x < 1 时 F(x) = (x-1)²；当 x ≥1 时 F(x) = x(ln x+1)+1(D) F(x)：当 x < 1 时 F(x) = (x-1)²；当 x ≥1 时 F(x) = x(ln x-1)+1","a":"D。"},{"y":2018,"o":15,"s":"求不定积分 ∫ e²ˣarctan√(eˣ-1) dx。","a":"(e²ˣarctan√(eˣ-1))/2-dfrac16(eˣ-1)^(frac32)-dfrac12√(eˣ-1)+C（C 为任意常数）。"},{"y":2019,"o":16,"s":"求不定积分 ∫(3x+6)/((x-1)²(x²+x+1)) dx。","a":"-2ln|x-1|-3/(x-1)+ln(x²+x+1)+C（C 为任意常数）。"},{"y":2023,"o":2,"s":"函数 f(x)：当 x ≤0 时 f(x) = 1/(√(1+x²))；当 x > 0 时 f(x) = (x+1)cos x。则 f(x) 的一个原函数为（ ）(A) F(x)：当 x ≤0 时 F(x) = ln(√(1+x²)-x)；当 x > 0 时 F(x) = (x+1)cos x-sin x(B) F(x)：当 x ≤0 时 F(x) = ln(√(1+x²)-x)+1；当 x > 0 时 F(x) = (x+1)cos x-sin x(C) F(x)：当 x ≤0 时 F(x) = ln(√(1+x²)+x)；当 x > 0 时 F(x) = (x+1)sin x+cos x(D) F(x)：当 x ≤0 时 F(x) = ln(√(1+x²)+x)+1；当 x > 0 时 F(x) = (x+1)sin x+cos x","a":"D。"}],"Kc023f098|2":[{"y":2010,"o":16,"s":"I. 比较 ∫₀¹|ln t|[ln(1+t)]ⁿdt 与 ∫₀¹ tⁿ|ln t|dt（n = 1,2,⋯）的大小，说明理由；II. 记 uₙ = ∫₀¹|ln t|[ln(1+t)]ⁿdt（n = 1,2,⋯），求极限 lim_(n → ∞)uₙ。","a":"I. 前者小于后者；II. 极限为 0。"},{"y":2011,"o":6,"s":"设 I = ∫₀^(fracπ4)ln(sin x) dx，J = ∫₀^(fracπ4)ln(cot x) dx，K = ∫₀^(fracπ4)ln(cos x) dx，则 I、J、K 的大小关系为（ ）(A) I < J < K (B) I < K < J (C) J < I < K (D) K < J < I","a":"B。"},{"y":2012,"o":4,"s":"设 Iₖ = ∫₀^(kπ)e^(x²)sin x dx（k = 1,2,3），则有（ ）(A) I₁ < I₂ < I₃ (B) I₃ < I₂ < I₁ (C) I₂ < I₃ < I₁ (D) I₂ < I₁ < I₃","a":"D。"},{"y":2012,"o":10,"s":"lim_(n → ∞)n(1/(1+n²)+1/(2²+n²)+⋯+1/(n²+n²)) = underline。","a":"dfracπ4。"},{"y":2016,"o":10,"s":"极限 lim_(n → ∞)1/n²(sinfrac1n+2sinfrac2n+⋯+nsinfracnn) = underline。","a":"sin 1-cos 1。"},{"y":2017,"o":17,"s":"求 lim_(n → ∞)∑ₖ₌₁ⁿk/n²ln(1+frackn)。","a":"dfrac14。"},{"y":2018,"o":5,"s":"设 M = ∫_(-fracπ2)^(fracπ2)((1+x)²)/(1+x²) dx，N = ∫_(-fracπ2)^(fracπ2)(1+x)/eˣ dx，K = ∫_(-fracπ2)^(fracπ2)(1+√(cos x))dx，则（ ）(A) M > N > K (B) M > K > N (C) K > M > N (D) K > N > M","a":"C。"},{"y":2021,"o":7,"s":"设函数 f(x) 在区间 [0,1] 上连续，则 ∫₀¹ f(x) dx = （ ）(A) lim_(n → ∞)∑ₖ₌₁ⁿ f((2k-1)/2n)1/2n(B) lim_(n → ∞)∑ₖ₌₁ⁿ f((2k-1)/2n)1/n(C) lim_(n → ∞)∑ₖ₌₁²ⁿ f((k-1)/2n)1/n(D) lim_(n → ∞)∑ₖ₌₁²ⁿ f(k/2n)2/n","a":"B。"},{"y":2022,"o":7,"s":"若 I₁ = ∫₀¹x/(2(1+cos x)) dx，I₂ = ∫₀¹(ln(1+x))/(1+cos x) dx，I₃ = ∫₀¹2x/(1+sin x) dx，则（ ）(A) I₁ < I₂ < I₃ (B) I₂ < I₁ < I₃ (C) I₁ < I₃ < I₂ (D) I₃ < I₂ < I₁","a":"A。"},{"y":2025,"o":13,"s":"lim_(n → ∞)1/n²[lnfrac1n+2lnfrac2n+⋯+(n-1)ln(n-1)/n] = underline。","a":"-dfrac14。"}],"Kc431f98f|2":[{"y":2009,"o":11,"s":"lim_(n → ∞)∫₀¹ e⁻ˣsin nx dx = underline。","a":"0。"},{"y":2014,"o":10,"s":"设 f(x) 是周期为 4 的可导奇函数，且 f'(x) = 2(x-1)，x∈[0,2]，则 f(7) = underline。","a":"1。"},{"y":2016,"o":16,"s":"设函数 f(x) = ∫₀¹|t²-x²| dt（x > 0），求 f'(x)，并求 f(x) 的最小值。","a":"f'(x) = 4x²-2x（0 < x < 1），f'(x) = 2x（x ≥1）；最小值为 f(dfrac12) = dfrac14。"},{"y":2019,"o":13,"s":"已知函数 f(x) = x∫₁ˣ(sin t²)/t dt，则 ∫₀¹ f(x) dx = underline。","a":"dfrac14(cos1-1)。"},{"y":2020,"o":3,"s":"∫₀¹(arcsin√(x))/(√(x(1-x))) dx = （ ）(A) π²/4(B) π²/8(C) π/4(D) π/8","a":"A。"},{"y":2022,"o":13,"s":"∫₀¹(2x+3)/(x²-x+1) dx = underline。","a":"(8sqrt3π)/9。"},{"y":2023,"o":15,"s":"设连续函数 f(x) 满足 f(x+2)-f(x) = x，∫₀² f(x) dx = 0，则 ∫₁³ f(x) dx = underline。","a":"dfrac12。"},{"y":2025,"o":17,"s":"计算 ∫₀¹1/((x+1)(x²-2x+2)) dx。","a":"(3ln2+π)/10。"},{"y":2026,"o":15,"s":"函数 f(x) = ln(2+x) 在区间 [0,2] 上的平均值为 underline。","a":"3ln2-1。"}],"K8d94766f|3":[{"y":2014,"o":1,"s":"lim_(n → ∞)aₙ = a，且 a ≠0，则当 n 充分大时有（ ）(A) |aₙ| > |a|/2 (B) |aₙ| < |a|/2 (C) aₙ > a-dfrac1n (D) aₙ < a+dfrac1n","a":"A。"},{"y":2015,"o":1,"s":"设 {xₙ} 是数列。下列命题中不正确的是（ ）(A) 若 lim xₙ = a，则 lim x₂ₙ = lim x₂ₙ₊₁ = a(B) 若 lim x₂ₙ = lim x₂ₙ₊₁ = a，则 lim xₙ = a(C) 若 lim xₙ = a，则 lim x₃ₙ = lim x₃ₙ₊₁ = a(D) 若 lim x₃ₙ = lim x₃ₙ₊₁ = a，则 lim xₙ = a","a":"D。"},{"y":2022,"o":2,"s":"已知 aₙ = sqrt[n]n-((-1)ⁿ)/n (n = 1,2,⋯)，则 {aₙ}（ ）(A) 有最大值，有最小值 (B) 有最大值，没有最小值(C) 没有最大值，有最小值 (D) 没有最大值，没有最小值","a":"A。"}],"K61b15cc0|3":[{"y":2018,"o":19,"s":"设数列 {xₙ} 满足：x₁ > 0，xₙ e^(xₙ₊₁) = e^(xₙ)-1 (n = 1,2,⋯)。证明 {xₙ} 收敛，并求 lim_(n → ∞)xₙ。","a":"lim_(n → ∞)xₙ = 0。"}],"Kc5c67202|3":[{"y":2009,"o":9,"s":"lim_(x → 0)(e-e^(cos x))/(sqrt[3]1+x²-1) = ________。","a":"3e/2。"},{"y":2010,"o":15,"s":"求极限 lim_(x → +∞)(x^(frac1x)-1)^(1/(ln x))。","a":"e⁻¹。"},{"y":2011,"o":9,"s":"设 f(x) = lim_(t → 0)x(1+3t)^(x/t)，则 f'(x) = ________。","a":"(1+3x)e³ˣ。"},{"y":2011,"o":15,"s":"求极限 lim_(x → 0)(√(1+2sin x)-x-1)/(xln(1+x))。","a":"-dfrac12。"},{"y":2012,"o":9,"s":"lim_(x → fracπ4)(tan x)^(1/(cos x-sin x)) = ________。","a":"e^(-sqrt2)。"},{"y":2012,"o":15,"s":"求极限 lim_(x → 0)(e^(x²)-e^(2-2cos x))/x⁴。","a":"dfrac112。"},{"y":2014,"o":15,"s":"求极限 lim_(x → +∞)(∫₁ˣ[t²(e^(frac1t)-1)-t]dt)/(x²ln(1+frac1x))。","a":"dfrac12（与数学一、数学二 2014 第 15 题同题）。"},{"y":2015,"o":9,"s":"lim_(x → 0)(ln(cos x))/x² = ________。","a":"-dfrac12（与数学一 2015 第 9 题同题）。"},{"y":2016,"o":9,"s":"已知函数 f(x) 满足 lim_(x → 0)(√(1+f(x)sin2x)-1)/(e³ˣ-1) = 2，则 lim_(x → 0)f(x) = ________。","a":"6。"},{"y":2016,"o":15,"s":"求极限 lim_(x → 0)(cos2x+2xsin x)^(1/x⁴)。","a":"e^(frac13)（与数学二 2016 第 15 题同题）。"},{"y":2017,"o":15,"s":"求极限 lim_(x → 0⁺)(∫₀ˣ√(x-t) eᵗ dt)/(√(x³))。","a":"dfrac23。"},{"y":2020,"o":1,"s":"设 lim_(x → a)(f(x)-a)/(x-a) = b，则 lim_(x → a)(sin f(x)-sin a)/(x-a) = （ ）(A) bsin a (B) bcos a (C) bsin f(a) (D) bcos f(a)","a":"B。"},{"y":2022,"o":11,"s":"lim_(x → 0)((1+eˣ)/2)^(cot x) = ________。","a":"sqrte（与数学二 2022 第 11 题同题）。"},{"y":2023,"o":11,"s":"lim_(x → ∞)x²(2-xsinfrac1x-cosfrac1x) = ________。","a":"dfrac23。"},{"y":2026,"o":12,"s":"lim_(x → 0)dfrac1x((√(1+x²))/(sin x)-1/(tan x)) = ________。","a":"1。"}],"K2b11ab18|3":[{"y":2019,"o":9,"s":"lim_(n → ∞)[1/(1·2)+1/(2·3)+⋯+1/(n(n+1))]ⁿ = ________。","a":"e⁻¹（即 dfrac1e）。"}],"Kcdaedae1|3":[{"y":2013,"o":1,"s":"当 x → 0 时，用 \"o(x)\" 表示比 x 高阶的无穷小量，则下列式子中错误的是（ ）(A) x· o(x²) = o(x³) (B) o(x)· o(x²) = o(x³) (C) o(x²)+o(x²) = o(x²) (D) o(x)+o(x²) = o(x²)","a":"D。"},{"y":2021,"o":1,"s":"当 x → 0 时，∫₀^(x²)(e^(t³)-1) dt 是 x⁷ 的（ ）(A) 低阶无穷小 (B) 等价无穷小 (C) 高阶无穷小 (D) 同阶但非等价无穷小","a":"C。"},{"y":2022,"o":1,"s":"若当 x → 0 时，α(x)、β(x) 是非零无穷小量，则以下四个命题：① 若 α(x)∼β(x)，则 α²(x)∼β²(x)；② 若 α²(x)∼β²(x)，则 α(x)∼β(x)；③ 若 α(x)∼β(x)，则 α(x)-β(x) = o(α(x))；④ 若 α(x)-β(x) = o(α(x))，则 α(x)∼β(x)。其中所有真命题的序号是（ ）(A) ①③ (B) ①④ (C) ①③④ (D) ②③④","a":"C。"},{"y":2024,"o":11,"s":"当 x → 0 时，∫₀ˣ((1+t²)sin t²)/(1+cos²t) dt 与 xᵏ 是同阶无穷小，则 k = ________。","a":"k = 3。"},{"y":2025,"o":1,"s":"在 x → 0⁺ 时，下列无穷小量中与 x 等价的是（ ）(A) e^(-sin x)-1 (B) √(x+1)-cos x (C) 1-cos√(2x) (D) 1-(ln(1+x))/x","a":"C。"}],"Ke9053521|3":[{"y":2009,"o":2,"s":"当 x → 0 时，f(x) = x-sin ax 与 g(x) = x²ln(1-bx) 是等价无穷小，则（ ）(A) a = 1, b = -dfrac16 (B) a = 1, b = dfrac16 (C) a = -1, b = -dfrac16 (D) a = -1, b = dfrac16","a":"A（a = 1，b = -dfrac16）。"},{"y":2010,"o":1,"s":"若 lim_(x → 0)[dfrac1x-(dfrac1x-a)eˣ] = 1，则 a 等于（ ）(A) 0 (B) 1 (C) 2 (D) 3","a":"C（a = 2）。"},{"y":2011,"o":1,"s":"已知当 x → 0 时，函数 f(x) = 3sin x-sin 3x 与 c xᵏ 是等价无穷小，则（ ）(A) k = 1, c = 4 (B) k = 1, c = -4 (C) k = 3, c = 4 (D) k = 3, c = -4","a":"C（k = 3，c = 4）。"},{"y":2013,"o":15,"s":"当 x → 0 时，1-cos x·cos 2x·cos 3x 与 a xⁿ 为等价无穷小，求 n 与 a 的值。","a":"n = 2，a = 7。"},{"y":2014,"o":3,"s":"设 p(x) = a+bx+cx²+dx³。当 x → 0 时，若 p(x)-tan x 是比 x³ 高阶的无穷小，则下列选项中错误的是（ ）(A) a = 0 (B) b = 1 (C) c = 0 (D) d = dfrac16","a":"D（实际 d = dfrac13）。"},{"y":2015,"o":15,"s":"设函数 f(x) = x+aln(1+x)+bxsin x，g(x) = kx³。若 f(x) 与 g(x) 在 x → 0 时是等价无穷小，求 a,b,k 的值。","a":"a = -1，b = -dfrac12，k = -dfrac13。"},{"y":2018,"o":15,"s":"已知实数 a,b 满足 lim_(x → +∞)[(ax+b)e^(frac1x)-x] = 2，求 a,b。","a":"a = 1，b = 1。"},{"y":2019,"o":1,"s":"当 x → 0 时，若 x-tan x 与 xᵏ 是同阶无穷小，则 k = （ ）(A) 1 (B) 2 (C) 3 (D) 4","a":"C（k = 3）。"},{"y":2020,"o":15,"s":"已知 a,b 为常数，若 (1+dfrac1n)ⁿ-e 与 b/nᵃ 在 n → ∞ 时是等价无穷小，求 a,b。","a":"a = 1，b = -dfrace2。"},{"y":2021,"o":17,"s":"已知 lim_(x → 0)[aarctandfrac1x+(1+|x|)^(frac1x)] 存在，求 a 的值。","a":"a = 1/π(dfrac1e-e)。"}],"K71a29108|3":[{"y":2009,"o":1,"s":"函数 f(x) = (x-x³)/(sinπ x) 的可去间断点的个数为（ ）(A) 1 (B) 2 (C) 3 (D) 无穷多个","a":"C，共 3 个可去间断点，x = 0, ±1。"},{"y":2013,"o":2,"s":"函数 f(x) = (|x|ˣ-1)/(x(x+1)ln|x|) 的可去间断点的个数为（ ）(A) 0 (B) 1 (C) 2 (D) 3","a":"C，共 2 个可去间断点，x = 0, 1。"},{"y":2017,"o":1,"s":"设函数f(x) = (1-cos√(x))/ax (x > 0), f(x) = b (x ≤0)在 x = 0 处连续，则（ ）(A) ab = dfrac12 (B) ab = -dfrac12 (C) ab = 0 (D) ab = 2","a":"A，ab = dfrac12。"},{"y":2020,"o":2,"s":"函数 f(x) = (e^(frac1x-1)ln|1+x|)/((eˣ-1)(x-2)) 的第二类间断点的个数为（ ）(A) 1 (B) 2 (C) 3 (D) 4","a":"C，共 3 个第二类间断点，x = -1, 1, 2。"},{"y":2024,"o":1,"s":"设函数 f(x) = lim_(n → ∞)(1+x)/(1+nx²ⁿ)，则 f(x)，（ ）(A) 在 x = 1,x = -1 处都连续(B) 在 x = 1 处连续，在 x = -1 处不连续(C) 在 x = 1,x = -1 处都不连续(D) 在 x = 1 处不连续，在 x = -1 处连续","a":"D，在 x = 1 处不连续，在 x = -1 处连续。"}],"K547f1fa4|3":[{"y":2011,"o":2,"s":"设函数 f(x) 在 x = 0 处可导，且 f(0) = 0，则 lim_(x → 0)(x²f(x)-2f(x³))/x³ = （ ）(A) -2f'(0) (B) -f'(0) (C) f'(0) (D) 0","a":"B，极限为 -f'(0)。"},{"y":2015,"o":19,"s":"I. 设函数 u(x),v(x) 可导，利用导数定义证明 [u(x)v(x)]' = u'(x)v(x)+u(x)v'(x)；II. 设函数 u₁(x),u₂(x),⋯,uₙ(x) 可导，f(x) = u₁(x)u₂(x)⋯ uₙ(x)，写出 f(x) 的求导公式。","a":"第 I 问证明见"},{"y":2018,"o":1,"s":"下列函数中，在 x = 0 处不可导的是（ ）(A) f(x) = |x|sin|x| (B) f(x) = |x|sin√(|x|) (C) f(x) = cos|x| (D) f(x) = cos√(|x|)","a":"D。"},{"y":2018,"o":12,"s":"设函数 f(x) 满足 f(x+Δ x)-f(x) = 2xf(x)Δ x+o(Δ x) (Δ x → 0)，且 f(0) = 2，则 f(1) ______","a":"2e。"},{"y":2021,"o":2,"s":"函数f(x) = (eˣ-1)/x (x ≠0), f(x) = 1 (x = 0)在 x = 0 处（ ）(A) 连续且取极大值 (B) 连续且取极小值 (C) 可导且导数为零 (D) 可导且导数不为零","a":"D。"},{"y":2025,"o":18,"s":"设函数 f(x) 在 x = 0 处连续，且 lim_(x → 0)(xf(x)-e^(2sin x)+1)/(ln(1+x)+ln(1-x)) = -3，证明 f(x) 在 x = 0 处可导，并求 f'(0)。","a":"f(x) 在 x = 0 处可导，且 f'(0) = 5（同时 f(0) = 2）。"}],"Kde439863|3":[{"y":2012,"o":2,"s":"设函数 f(x) = (eˣ-1)(e²ˣ-2)⋯(eⁿˣ-n)，其中 n 为正整数，则 f'(0) = （ ）(A) (-1)ⁿ⁻¹(n-1)! (B) (-1)ⁿ(n-1)! (C) (-1)ⁿ⁻¹n! (D) (-1)ⁿn!","a":"A，f'(0) = (-1)ⁿ⁻¹(n-1)!。"},{"y":2012,"o":10,"s":"设函数f(x) = ln√(x) (x ≥1), f(x) = 2x-1 (x < 1),y = f(f(x))，则 dy/dx|ₓ₌ₑ = ______","a":"dfrac1e。"},{"y":2021,"o":11,"s":"若 y = cos e^(-√(x))，则 dy/dx|ₓ₌₁ = ______","a":"(sin e⁻¹)/2e，即 (sin(1/e))/2e。"},{"y":2022,"o":13,"s":"已知函数 f(x) = e^(sin x)+e^(-sin x)，则 f'''(2π) = ______","a":"0。"}],"K58d92a92|3":[{"y":2011,"o":11,"s":"曲线 tan(x+y+dfracπ4) = eʸ 在点 (0,0) 处的切线方程为 underline。","a":"y = -2x（或 2x+y = 0）。"},{"y":2013,"o":9,"s":"设曲线 y = f(x) 与 y = x²-x 在点 (1,0) 处有公共切线，则 lim_(n → ∞)n f (n/(n+2)) = underline。","a":"-2。"},{"y":2020,"o":10,"s":"曲线 x+y+e²ˣʸ = 0 在点 (0,-1) 处的切线方程为 underline。","a":"y = x-1（或 x-y-1 = 0）。"}],"Kdd1ee30c|3":[{"y":2010,"o":3,"s":"设函数 f(x),g(x) 具有二阶导数，且 g''(x) < 0。若 g(x₀) = a 是 g(x) 的极值，则 f(g(x)) 在 x₀ 处取极大值的一个充分条件是（ ）(A) f'(a) < 0(B) f'(a) > 0(C) f''(a) < 0(D) f''(a) > 0","a":"B。"},{"y":2016,"o":17,"s":"设函数 f(x) = ∫₀¹|t²-x²| dt (x > 0)，求 f'(x)，并求 f(x) 的最小值。","a":"当 0 < x < 1 时 f'(x) = 4x²-2x，当 x ≥1 时 f'(x) = 2x；最小值为 dfrac14（在 x = dfrac12 处取得）。"},{"y":2017,"o":3,"s":"设函数 f(x) 可导，且 f(x)f'(x) > 0，则（ ）(A) f(1) > f(-1)(B) f(1) < f(-1)(C) |f(1)| > |f(-1)|(D) |f(1)| < |f(-1)|","a":"C。"},{"y":2019,"o":15,"s":"已知函数：当 x > 0 时 f(x) = x²ˣ，当 x ≤0 时 f(x) = xeˣ+1。求 f'(x)，并求 f(x) 的极值。","a":"当 x < 0 时 f'(x) = eˣ(x+1)，当 x > 0 时 f'(x) = 2e^(2xln x)(ln x+1)；x = 0 处不可导。极小值 f(-1) = 1-dfrac1e、f(dfrac1e) = "},{"y":2023,"o":17,"s":"已知可导函数 y = y(x) 满足 aeˣ+y²+y-ln(1+x)cos y+b = 0，且 y(0) = 0，y'(0) = 0。Ⅰ. 求 a,b 的值；Ⅱ. 判断 x = 0 是否为 y(x) 的极值点。","a":"Ⅰ. a = 1，b = -1；Ⅱ. x = 0 是 y(x) 的极大值点。"}],"Kac3d5ac3|3":[{"y":2010,"o":12,"s":"若曲线 y = x³+ax²+bx+1 有拐点 (-1,0)，则 b = underline。","a":"b = 3。"},{"y":2012,"o":1,"s":"曲线 y = (x²+x)/(x²-1) 的渐近线的条数为（ ）(A) 0(B) 1(C) 2(D) 3","a":"C。"},{"y":2014,"o":2,"s":"下列曲线中有渐近线的是（ ）(A) y = x+sin x(B) y = x²+sin x(C) y = x+sindfrac1x(D) y = x²+sindfrac1x","a":"C。"},{"y":2014,"o":4,"s":"设函数 f(x) 具有 2 阶导数，g(x) = f(0)(1-x)+f(1)x，则在区间 [0,1] 上（ ）(A) 当 f'(x) ≥0 时，f(x) ≥ g(x)(B) 当 f'(x) ≥0 时，f(x) ≤ g(x)(C) 当 f''(x) ≥0 时，f(x) ≥ g(x)(D) 当 f''(x) ≥0 时，f(x) ≤ g(x)","a":"D。"},{"y":2015,"o":2,"s":"设函数 f(x) 在 (-∞,+∞) 内连续，其 2 阶导函数 f''(x) 的图形如图所示，则曲线 y = f(x) 的拐点个数为（ ）(A) 0(B) 1(C) 2(D) 3（图形说明：横轴为 x，纵轴为 f''(x)；f''(x) 的图像与 x 轴在 x₁ 处相切而不穿过，在 x = 0 处断开（f''(0) 不存在）且由正变负，在 x₂ 处穿过 x 轴由负变正。）","a":"C。"},{"y":2016,"o":1,"s":"设函数 f(x) 在 (-∞,+∞) 内连续，其导函数的图形如图所示，则（ ）(A) 函数 f(x) 有 2 个极值点，曲线 y = f(x) 有 2 个拐点(B) 函数 f(x) 有 2 个极值点，曲线 y = f(x) 有 3 个拐点(C) 函数 f(x) 有 3 个极值点，曲线 y = f(x) 有 1 个拐点(D) 函数 f(x) 有 3 个极值点，曲线 y = f(x) 有 2 个拐点（图形说明：横轴为 x，纵轴为 f'(x)；f'(x) 图像在 x₁ 处由正变负穿过 x 轴，在 x₂ 处断裂为竖直虚线（f'(x) 无定义），在 x₃ 处由负变正穿过 x 轴，在 x₄ 处与 x 轴相切而不改号；f'(x) 的单调性在 x₂、x₅、x₄ 处发生改变，其中 x₅ 为 f'(x) 的局部极大点。）","a":"B。"},{"y":2018,"o":2,"s":"设函数 f(x) 在 [0,1] 上二阶可导，且 ∫₀¹ f(x) dx = 0，则（ ）(A) 当 f'(x) < 0 时，f(dfrac12) < 0(B) 当 f''(x) < 0 时，f(dfrac12) < 0(C) 当 f'(x) > 0 时，f(dfrac12) < 0(D) 当 f''(x) > 0 时，f(dfrac12) < 0","a":"D。"},{"y":2018,"o":9,"s":"曲线 y = x²+2ln x 在其拐点处的切线方程是 underline。","a":"y = 4x-3。"},{"y":2019,"o":10,"s":"曲线 y = xsin x+2cos x (-π/2 < x < 3π/2) 的拐点坐标为 underline。","a":"(π,-2)。"},{"y":2025,"o":2,"s":"已知函数 f(x) = ∫₀ˣ e^(t²)sin t dt，g(x) = ∫₀ˣ e^(t²) dt·sin² x，则（ ）(A) x = 0 是 f(x) 的极值点，也是 g(x) 的极值点(B) x = 0 是 f(x) 的极值点，(0,0) 是曲线 y = g(x) 的拐点(C) x = 0 是 f(x) 的极值点，(0,0) 是曲线 y = f(x) 的拐点(D) (0,0) 是曲线 y = f(x) 的拐点，(0,0) 也是曲线 y = g(x) 的拐点","a":"B。"},{"y":2025,"o":11,"s":"设 g(x) 是函数 f(x) = dfrac12ln(3+x)/(3-x) 的反函数，则曲线 y = g(x) 的渐近线方程为 underline。","a":"y = 3 和 y = -3。"},{"y":2026,"o":1,"s":"曲线 y = xe^(1/x)（ ）(A) 无水平渐近线，无铅直渐近线(B) 有水平渐近线，有铅直渐近线(C) 无水平渐近线，有铅直渐近线(D) 有水平渐近线，无铅直渐近线","a":"C。"}],"K0318406f|3":[{"y":2011,"o":18,"s":"证明方程 4arctan x-x+4π/3-sqrt3 = 0 恰有两个实根。","a":"恰有两个实根，分别为 x = -sqrt3 与位于 (sqrt3,+∞) 内的一个根。"},{"y":2017,"o":18,"s":"已知方程 dfrac1ln(1+x)-dfrac1x = k 在区间 (0,1) 内有实根，确定常数 k 的取值范围。","a":"k∈(dfrac1ln2-1,dfrac12)。"},{"y":2019,"o":2,"s":"已知方程 x⁵-5x+k = 0 有 3 个不同的实根，则 k 的取值范围是（ ）(A) (-∞,-4)(B) (4,+∞)(C) {-4,4}(D) (-4,4)","a":"D。"},{"y":2021,"o":3,"s":"设函数 f(x) = ax-bln x (a > 0) 有两个零点，则 dfracba 的取值范围是（ ）(A) (e,+∞)(B) (0,e)(C) (0,1/e)(D) (1/e,+∞)","a":"A。"}],"Kbd198003|3":[{"y":2010,"o":4,"s":"设 f(x) = ln¹⁰x，g(x) = x，h(x) = e^(x/10)，则当 x 充分大时有（ ）(A) g(x) < h(x) < f(x)(B) h(x) < g(x) < f(x)(C) f(x) < g(x) < h(x)(D) g(x) < f(x) < h(x)","a":"C。"},{"y":2012,"o":18,"s":"证明 xln(1+x)/(1-x)+cos x ≥1+x²/2（-1 < x < 1）。","a":"证明题，不等式在 -1 < x < 1 上恒成立。"}],"K4586eb88|3":[{"y":2009,"o":18,"s":"I. 证明拉格朗日中值定理：若函数 f(x) 在 [a,b] 上连续，在 (a,b) 内可导，则存在 ξ∈(a,b)，使得 f(b)-f(a) = f'(ξ)(b-a)。II. 证明：若函数 f(x) 在 x = 0 处连续，在 (0,δ)（δ > 0）内可导，且 lim_(x → 0⁺)f'(x) = A，则 f'₊(0) 存在，且 f'₊(0) = A。","a":"证明题，两问结论均成立。"},{"y":2010,"o":19,"s":"设函数 f(x) 在 [0,3] 上连续，在 (0,3) 内存在二阶导数，且 2f(0) = ∫₀² f(x) dx = f(2)+f(3)。I. 证明存在 η∈(0,2)，使 f(η) = f(0)；II. 证明存在 ξ∈(0,3)，使 f''(ξ) = 0。","a":"证明题，两问结论均成立。"},{"y":2013,"o":19,"s":"设函数 f(x) 在 [0,+∞) 上可导，f(0) = 0 且 lim_(x → +∞)f(x) = 2。证明：I. 存在 a > 0，使得 f(a) = 1；II. 对第 I 问中的 a，存在 ξ∈(0,a)，使得 f'(ξ) = dfrac1a。","a":"证明题，两问结论均成立。"},{"y":2019,"o":19,"s":"设 aₙ = ∫₀¹ xⁿ√(1-x²) dx（n = 0,1,2,⋯）。I. 证明数列 {aₙ} 单调递减，且 aₙ = (n-1)/(n+2)aₙ₋₂（n = 2,3,⋯）；II. 求 lim_(n → ∞)aₙ/(aₙ₋₁)。","a":"{aₙ} 单调递减；aₙ = (n-1)/(n+2)aₙ₋₂；lim_(n → ∞)aₙ/(aₙ₋₁) = 1。"},{"y":2020,"o":19,"s":"设函数 f(x) 在区间 [0,2] 上具有连续导数，f(0) = f(2) = 0，M = max_(x∈[0,2]){|f(x)|}。证明：I. 存在 ξ∈(0,2)，使得 |f'(ξ)| ≥ M；II. 若对任意的 x∈(0,2)，|f'(x)| ≤ M，则 M = 0。","a":"证明题，两问结论均成立。"},{"y":2025,"o":20,"s":"设函数 f(x) 在区间 (a,b) 内可导，证明导函数 f'(x) 在 (a,b) 内严格单调增加的充分必要条件是：对 (a,b) 内任意的 x₁,x₂,x₃，当 x₁ < x₂ < x₃ 时，(f(x₂)-f(x₁))/(x₂-x₁) < (f(x₃)-f(x₂))/(x₃-x₂).","a":"证明题，必要性与充分性均成立。"}],"K167393e9|3":[{"y":2023,"o":20,"s":"设函数 f(x) 在 [-a,a] 上有二阶连续导数。证明：I. 若 f(0) = 0，则存在 ξ∈(-a,a)，使得 f''(ξ) = 1/a²[f(a)+f(-a)]；II. 若 f(x) 在 (-a,a) 内取得极值，则存在 η∈(-a,a)，使得 |f''(η)| ≥1/2a²|f(a)-f(-a)|。","a":"证明题，两问结论均成立。"},{"y":2024,"o":20,"s":"设函数 f(x) 具有 2 阶导数，且 f'(0) = f'(1)，|f''(x)| ≤1。证明：I. 当 x∈(0,1) 时，|f(x)-f(0)(1-x)-f(1)x| ≤ (x(1-x))/2；II. |∫₀¹ f(x) dx-(f(0)+f(1))/2| ≤1/12。","a":"证明题，两问结论均成立。"}],"Kf3b906ca|3":[{"y":2009,"o":12,"s":"设某产品的需求函数为 Q = Q(p)，其对价格 p 的弹性 εₚ = 0.2，则当需求量为 10000 件时，价格增加 1 元会使产品收益增加 ______ 元。","a":"8000。"},{"y":2010,"o":11,"s":"设某商品的收益函数为 R(p)，收益弹性为 1+p³，其中 p 为价格，且 R(1) = 1，则 R(p) = ______。","a":"R(p) = p e^((p³-1)/3)。"},{"y":2013,"o":18,"s":"设生产某商品的固定成本为 60000 元，可变成本为 20 元/件，价格函数为 p = 60-Q/(1000)（p 是单价，单位：元；Q 是销量，单位：件）。已知产销平衡，求：I. 该商品的边际利润；II. 当 p = 50 时的边际利润，并解释其经济意义；III. 使得利润最大的定价 p。","a":"I. L'(Q) = 40-Q/500；II. 边际利润为 20，即销量 10000 件时再多销售 1 件可增加利润约 20 元；III. p = 40 元。"},{"y":2014,"o":9,"s":"设某商品的需求函数为 Q = 40-2P（P 为商品的价格），则该商品的边际收益为 ______。","a":"R'(Q) = 20-Q。"},{"y":2015,"o":17,"s":"为了实现利润最大化，厂商需要对某商品确定其定价模型。设 Q 为该商品的需求量，p 为价格，MC 为边际成本，η 为需求弹性（η > 0）。I. 证明定价模型为p = MC/(1-1/η);II. 若该商品的成本函数为 C(Q) = 1600+Q²，需求函数为 Q = 40-p，试由第一问中的定价模型确定此商品的价格。","a":"I. 证明见"},{"y":2016,"o":16,"s":"设某商品的最大需求量为 1200 件，该商品的需求函数 Q = Q(p)，需求弹性 η = p/(120-p)（η > 0），p 为单价（万元）。I. 求需求函数的表达式；II. 求 p = 100 万元时的边际收益，并说明其经济意义。","a":"I. Q(p) = 1200-10p；II. 边际收益为 80 万元，即单价 100 万元、销量 200 件时，再销售 1 件（第 201 件）收益约增加 80 万元。"},{"y":2017,"o":11,"s":"设生产某产品的平均成本为 barC(Q) = 1+e^(-Q)，其中产量为 Q，则边际成本为 ______。","a":"C'(Q) = 1+e^(-Q)-Qe^(-Q)。"},{"y":2018,"o":4,"s":"设某产品的成本函数 C(Q) 可导，其中 Q 为产量。若产量为 Q₀ 时平均成本最小，则（ ）(A) C'(Q₀) = 0(B) C'(Q₀) = C(Q₀)(C) C'(Q₀) = Q₀C(Q₀)(D) Q₀C'(Q₀) = C(Q₀)","a":"D。"},{"y":2019,"o":12,"s":"以 P_A、P_B 分别表示 A、B 两个商品的价格，设商品 A 的需求函数 Q_A = 500-P_A²-P_AP_B+2P_B²，则当 P_A = 10、P_B = 20 时，商品 A 的需求量对自身价格的弹性 η_(AA)（η_(AA) > 0） = ______。","a":"0.4。"},{"y":2020,"o":11,"s":"设某厂家生产某产品的产量为 Q，成本 C(Q) = 100+13Q，该产品的单价为 p，需求量 q(p) = 800/(p+3)-2，则该厂家获得最大利润时的产量为 ______。","a":"8。"},{"y":2022,"o":18,"s":"设某产品的产量 Q 由资本投入量 x 和劳动投入量 y 决定，生产函数 Q = 12x^(frac12)y^(frac16)，该产品的销售单价 p 与产量 Q 的关系为 p = 1160-1.5Q。若单位资本投入和单位劳动投入的价格分别为 6 和 8，求利润最大时的产量。","a":"Q = 384。"},{"y":2024,"o":14,"s":"某产品的价格函数为p = 25-0.25Q (Q ≤20),p = 35-0.75Q (Q > 20),其中 p 为单价，单位：万元；Q 为产量，单位：件。总成本函数为 C = 150+5Q+0.25Q²（万元），则经营该产品可获得的最大利润为 ______（万元）。","a":"50。"}],"K59e1e05f|3":[{"y":2009,"o":16,"s":"计算不定积分 ∫ln(1+√((1+x)/x))dx（x > 0）。","a":"xln(1+√((1+x)/x))+dfrac12ln(√(1+x)+√(x))-(√(x))/(2(√(1+x)+√(x)))+C（C 为任意常数）。"},{"y":2011,"o":17,"s":"求不定积分 ∫(arcsin√(x)+ln x)/(√(x)) dx。","a":"2√(x)arcsin√(x)+2√(x)ln x+2√(1-x)-4√(x)+C（C 为任意常数）。"},{"y":2018,"o":10,"s":"∫ eˣarcsin√(1-e²ˣ) dx = underline。","a":"eˣarcsin√(1-e²ˣ)-√(1-e²ˣ)+C。"},{"y":2023,"o":2,"s":"函数 f(x) = 1/(√(1+x²))（当 x ≤0），f(x) = (x+1)cos x（当 x > 0）的一个原函数为（ ）(A) F(x) = ln(√(1+x²)-x)（x ≤0）；F(x) = (x+1)cos x-sin x（x > 0）(B) F(x) = ln(√(1+x²)-x)+1（x ≤0）；F(x) = (x+1)cos x-sin x（x > 0）(C) F(x) = ln(√(1+x²)+x)（x ≤0）；F(x) = (x+1)sin x+cos x（x > 0）(D) F(x) = ln(√(1+x²)+x)+1（x ≤0）；F(x) = (x+1)sin x+cos x（x > 0）","a":"D。"}],"Kc023f098|3":[{"y":2010,"o":18,"s":"I. 比较 ∫₀¹|ln t|[ln(1+t)]ⁿdt 与 ∫₀¹ tⁿ|ln t|dt（n = 1,2,⋯）的大小，说明理由；II. 记 uₙ = ∫₀¹|ln t|[ln(1+t)]ⁿdt（n = 1,2,⋯），求极限 lim_(n → ∞)uₙ。","a":"第Ⅰ问中 ∫₀¹|ln t|[ln(1+t)]ⁿdt < ∫₀¹ tⁿ|ln t|dt；第Ⅱ问 lim_(n → ∞)uₙ = 0。"},{"y":2014,"o":19,"s":"设函数 f(x),g(x) 在区间 [a,b] 上连续，且 f(x) 单调增加，0 ≤ g(x) ≤1。证明：I. 0 ≤ ∫ₐˣ g(t) dt ≤ x-a，x∈[a,b]；II. ∫ₐ^(a+∫ₐᵇ g(t) dt)f(x) dx ≤ ∫ₐᵇ f(x)g(x) dx。","a":"证明题，两问结论见思路 4 的辅助函数证法与积分中值定理证法。"},{"y":2016,"o":10,"s":"极限 lim_(n → ∞)1/n²(sindfrac1n+2sindfrac2n+⋯+nsindfracnn) = underline。","a":"sin 1-cos 1。"},{"y":2017,"o":17,"s":"求 lim_(n → ∞)∑ₖ₌₁ⁿk/n²ln(1+frackn)。","a":"dfrac14。"},{"y":2018,"o":3,"s":"设 M = ∫_(-π/2)^(π/2)((1+x)²)/(1+x²) dx，N = ∫_(-π/2)^(π/2)(1+x)/eˣ dx，K = ∫_(-π/2)^(π/2)(1+√(cos x))dx，则（ ）(A) M > N > K (B) M > K > N (C) K > M > N (D) K > N > M","a":"C。"},{"y":2022,"o":4,"s":"若 I₁ = ∫₀¹x/(2(1+cos x)) dx，I₂ = ∫₀¹(ln(1+x))/(1+cos x) dx，I₃ = ∫₀¹2x/(1+sin x) dx，则（ ）(A) I₁ < I₂ < I₃ (B) I₂ < I₁ < I₃ (C) I₁ < I₃ < I₂ (D) I₃ < I₂ < I₁","a":"A。"}],"Kc431f98f|3":[{"y":2011,"o":4,"s":"设 I = ∫₀^(π/4)ln(sin x) dx，J = ∫₀^(π/4)ln(cot x) dx，K = ∫₀^(π/4)ln(cos x) dx，则 I,J,K 的大小关系为（ ）(A) I < J < K (B) I < K < J (C) J < I < K (D) K < J < I","a":"B。"},{"y":2014,"o":11,"s":"设 ∫₀ᵃ xe²ˣ dx = dfrac14，则 a = underline。","a":"a = dfrac12。"},{"y":2017,"o":9,"s":"∫_(-π)^π(sin³x+√(π²-x²))dx = underline。","a":"π³/2。"},{"y":2019,"o":11,"s":"已知函数 f(x) = ∫₁ˣ√(1+t⁴) dt，则 ∫₀¹ x²f(x) dx = underline。","a":"(1-2sqrt2)/18。"},{"y":2021,"o":12,"s":"∫_(sqrt5)⁵x/(√(|x²-9|)) dx = underline。","a":"6。"},{"y":2022,"o":12,"s":"∫₀²(2x-4)/(x²+2x+4) dx = underline。","a":"ln3-(sqrt3)/3π。"},{"y":2025,"o":17,"s":"计算 ∫₀¹1/((x+1)(x²-2x+2)) dx。","a":"(3ln2+π)/10。"},{"y":2026,"o":11,"s":"∫₀¹ x(x-1)(x-dfrac12)dx = underline。","a":"0。"}]};
